def decide(trace):
    from specflow.refmodel.temporal import after, eventually, worst

    supported = {1, 2, 4, 8}

    def applies(row):
        return (
            row['inputs'].get('cmd') in supported and
            row['inputs'].get('ena') == 1 and
            row['outputs'].get('fsm_active') == 1
        )

    def aborted(row):
        return (
            row['outputs'].get('al') == 1 or
            row['inputs'].get('nReset') == 0 or
            row['inputs'].get('rst') == 1
        )

    windows = after(
        trace,
        applies,
        until=lambda row: row['outputs'].get('cmd_ack') == 1,
        aborts=aborted
    )

    verdicts = []
    for window in windows:
        scl_initial = window.value('scl_oen')
        sda_initial = window.value('sda_oen')

        def control_activity(row):
            outputs = row['outputs']
            return (
                outputs.get('scl_oen') != scl_initial or
                outputs.get('sda_oen') != sda_initial
            )

        verdicts.append(
            eventually(
                window,
                control_activity,
                strong=False,
                after_activation=True
            )
        )

    return worst(verdicts)

def decide(trace):
    from specflow.refmodel.temporal import TO_END, WHILE_ACTIVE, after, eventually, throughout, worst

    def out(row, name):
        return row.get('outputs', {}).get(name)

    def inp(row, name):
        return row.get('inputs', {}).get(name)

    def reset(row):
        return inp(row, 'rst') == 1 or inp(row, 'nReset') == 0

    def command_windows(probe, abort_loss=False):
        return after(
            trace,
            lambda r: inp(r, 'ena') == 1 and out(r, probe) == 1,
            until=TO_END,
            aborts=(lambda r: reset(r) or (abort_loss and out(r, 'al') == 1))
        )

    verdicts = []

    for w in command_windows('start_sequence'):
        verdicts.append(eventually(w, lambda r: out(r, 'sda_oen') == 0, strong=False))
        verdicts.append(eventually(w, lambda r: out(r, 'scl_oen') == 0, strong=False))
        verdicts.append(eventually(w, lambda r: out(r, 'cmd_ack') == 1, strong=False))

    for w in command_windows('stop_sequence'):
        verdicts.append(eventually(w, lambda r: out(r, 'sda_oen') == 0, strong=False))
        verdicts.append(eventually(w, lambda r: out(r, 'scl_oen') == 1, strong=False))
        verdicts.append(eventually(w, lambda r: out(r, 'sda_oen') == 1, strong=False))
        verdicts.append(eventually(w, lambda r: out(r, 'cmd_ack') == 1, strong=False))

    for w in command_windows('write_sequence', abort_loss=True):
        verdicts.append(eventually(w, lambda r: out(r, 'scl_oen') == 1, strong=False))
        verdicts.append(eventually(w, lambda r: out(r, 'sda_oen') == (0 if w.value('din') == 0 else 1), strong=False))
        verdicts.append(eventually(w, lambda r: out(r, 'cmd_ack') == 1, strong=False))

    for w in command_windows('read_sequence', abort_loss=True):
        verdicts.append(eventually(w, lambda r: out(r, 'sda_oen') == 1, strong=False))
        verdicts.append(eventually(w, lambda r: out(r, 'scl_oen') == 1, strong=False))
        verdicts.append(eventually(w, lambda r: out(r, 'cmd_ack') == 1, strong=False))

    for w in after(
        trace,
        lambda r: out(r, 'sta_condition') == 1 and inp(r, 'ena') == 1,
        until=TO_END,
        aborts=reset
    ):
        verdicts.append(eventually(w, lambda r: out(r, 'busy') == 1, strong=False))

    for w in after(
        trace,
        lambda r: out(r, 'sto_condition') == 1 and inp(r, 'ena') == 1,
        until=TO_END,
        aborts=reset
    ):
        verdicts.append(eventually(w, lambda r: out(r, 'busy') == 0, strong=False))

    for w in after(
        trace,
        lambda r: out(r, 'write_high_phase') == 1 and inp(r, 'ena') == 1 and inp(r, 'din') == 1 and inp(r, 'sda_i') == 0,
        until=TO_END,
        aborts=reset
    ):
        verdicts.append(eventually(w, lambda r: out(r, 'al') == 1, strong=False))

    for probe in ('slave_wait', 'scl_sync'):
        waits = after(
            trace,
            lambda r, p=probe: inp(r, 'ena') == 1 and out(r, p) == 1,
            until=WHILE_ACTIVE,
            aborts=reset
        )
        for w in waits:
            verdicts.append(throughout(w, lambda r: out(r, 'scl_oen') == 1))

    return worst(verdicts)

def decide(trace):
    from specflow.refmodel.temporal import after, throughout, worst

    def active(row):
        return row['outputs'].get('fsm_active') == 1

    windows = after(
        trace,
        active,
        until=lambda row: not active(row)
    )

    return worst([
        throughout(
            w,
            lambda row: (
                row['outputs'].get('scl_o') == 0 and
                row['outputs'].get('sda_o') == 0
            ),
            after_activation=False
        )
        for w in windows
    ])

def decide(trace):
    operating_seen = False
    first_operating_edge = None

    for row in trace:
        probes = row.get('outputs', {})
        if probes.get('fsm_active') == 1:
            operating_seen = True
            if first_operating_edge is None:
                first_operating_edge = row.get('edge')

    if not operating_seen:
        return (None, None, 'fsm_active never asserted; the module operating situation did not occur')

    for row in trace:
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        if inputs.get('nReset', 1) == 0 or inputs.get('rst', 0) == 1:
            continue
        if outputs.get('scl_o') != 0 or outputs.get('sda_o') != 0:
            return (
                False,
                row.get('edge'),
                'during module operation, scl_o and sda_o must both remain constantly low'
            )

    return (
        True,
        first_operating_edge,
        'scl_o and sda_o remained constantly low throughout the observed operating trace'
    )

def decide(trace):
    transitions = []
    for i in range(1, len(trace)):
        before = trace[i - 1].get('outputs', {})
        after = trace[i].get('outputs', {})
        for port in ('scl_oen', 'sda_oen'):
            old = before.get(port)
            new = after.get(port)
            if old != new and new in (0, 1):
                transitions.append((trace[i], port, new))

    if not transitions:
        return (None, None, 'no scl_oen or sda_oen drive/release transition occurred in this trace')

    ports = sorted(set(port for _, port, _ in transitions))
    values = sorted(set(value for _, _, value in transitions))
    return (True, transitions[0][0].get('edge'),
            f'output-enable transition(s) observed on {", ".join(ports)} into value(s) {values}; the resolved external line is not a declared observable')

from specflow.refmodel.temporal import TO_END, after, eventually, worst

def decide(trace):
    def out(row, port, value):
        return row['outputs'].get(port) == value

    def probe(row, name):
        return row['outputs'].get(name) == 1

    def supported_bit_command(row):
        return any(probe(row, name) for name in (
            'start_sequence', 'stop_sequence',
            'read_sequence', 'write_sequence'))

    def active(row):
        return row['inputs'].get('ena') == 1 and supported_bit_command(row)

    def reset_or_loss(row):
        return (row['inputs'].get('nReset') == 0 or
                row['inputs'].get('rst') == 1 or
                out(row, 'al', 1))

    windows = after(trace, active,
                    until=lambda r: out(r, 'cmd_ack', 1),
                    aborts=reset_or_loss)

    return worst([
        eventually(w, lambda r: out(r, 'scl_oen', 0),
                    after_activation=False, strong=False)
        for w in windows
    ] + [
        eventually(w, lambda r: out(r, 'scl_oen', 1),
                    after_activation=False, strong=False)
        for w in windows
    ])

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, worst

    supported = (1, 2, 4, 8)

    def active_command(row):
        return (
            row['inputs'].get('cmd') in supported
            and row['inputs'].get('ena') == 1
            and row['outputs'].get('fsm_active') == 1
        )

    def acknowledged(row):
        return row['outputs'].get('cmd_ack') == 1

    def aborted(row):
        return (
            row['outputs'].get('al') == 1
            or row['inputs'].get('nReset') == 0
            or row['inputs'].get('rst') == 1
        )

    windows = after(
        trace,
        active_command,
        until=acknowledged,
        aborts=aborted,
    )

    def controls_a_line(row):
        return (
            row['outputs'].get('scl_oen') == 0
            or row['outputs'].get('sda_oen') == 0
        )

    return worst([
        eventually(
            w,
            controls_a_line,
            after_activation=True,
            strong=False,
        )
        for w in windows
    ])

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, worst

    def active_command(row):
        return (
            row['inputs'].get('ena') == 1
            and row['outputs'].get('fsm_active') == 1
        )

    def reset_asserted(row):
        return (
            row['inputs'].get('nReset') == 0
            or row['inputs'].get('rst') == 1
        )

    windows = after(
        trace,
        active_command,
        until=lambda r: r['outputs'].get('cmd_ack') == 1,
        aborts=reset_asserted,
    )

    def bit_level_generation(row):
        return (
            row['outputs'].get('scl_oen') == 0
            or row['outputs'].get('sda_oen') == 0
        )

    return worst([
        eventually(
            window,
            bit_level_generation,
            strong=False,
            after_activation=True,
        )
        for window in windows
    ])

def decide(trace):
    fall_edges = set()
    previous_nreset = None
    for row in trace:
        value = row['inputs'].get('nReset')
        if previous_nreset == 1 and value == 0:
            fall_edges.add(row['edge'])
        previous_nreset = value

    applicable = False
    for i, row in enumerate(trace):
        if row['edge'] not in fall_edges or i == 0:
            continue

        previous = trace[i - 1]
        previous_scl_oen = previous['outputs'].get('scl_oen')
        current_scl_oen = row['outputs'].get('scl_oen')

        if previous_scl_oen == 1:
            continue

        applicable = True
        if current_scl_oen != 1:
            return (False, row['edge'],
                    'after nReset fell while scl_oen was not reset, '
                    'scl_oen did not asynchronously change to released value 1')

        return (True, row['edge'],
                'nReset fell while scl_oen was not reset and scl_oen changed '
                'asynchronously to released value 1')

    if not applicable:
        return (None, None,
                'no applicable nReset falling transition occurred while '
                'scl_oen was away from its reset value')

    return (None, None, 'no applicable asynchronous reset transition was observed')

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, throughout

    def out(row, name, default=0):
        return row['outputs'].get(name, default)

    def inp(row, name, default=0):
        return row['inputs'].get(name, default)

    ena_falls = edges(trace, 'ena', 'fall')

    def applies(row):
        return (
            row['edge'] in ena_falls
            and inp(row, 'ena') == 0
            and inp(row, 'nReset') == 1
            and inp(row, 'rst') == 0
            and out(row, 'fsm_active') == 1
            and out(row, 'al') == 0
            and out(row, 'slave_wait') == 0
        )

    def aborted(row):
        return (
            inp(row, 'nReset') == 0
            or inp(row, 'rst') == 1
            or out(row, 'al') == 1
            or out(row, 'slave_wait') == 1
        )

    windows = after(
        trace,
        applies,
        until=lambda row: inp(row, 'ena') == 1,
        aborts=aborted,
    )

    if not windows:
        return (None, None, 'ena did not fall during an active command')

    for window in windows:
        quiet = throughout(
            window,
            lambda row: out(row, 'cmd_ack') == 0,
        )
        if quiet[0] is False:
            return quiet

        trigger_edge = window.edge
        close_row = None
        close_kind = None
        for row in trace:
            if row['edge'] <= trigger_edge:
                continue
            if inp(row, 'nReset') == 0 or inp(row, 'rst') == 1 or out(row, 'al') == 1 or out(row, 'slave_wait') == 1:
                close_row = row
                close_kind = 'aborted'
                break
            if inp(row, 'ena') == 1:
                close_row = row
                close_kind = 'resumed'
                break

        if close_kind != 'resumed':
            return (None, trigger_edge, 'ena remained low or the routed command was aborted before resumption')

        resumed = after(
            trace,
            lambda row, edge=close_row['edge']: row['edge'] == edge,
            until=TO_END,
            aborts=aborted,
        )
        completion = eventually(
            resumed[0],
            lambda row: out(row, 'cmd_ack') == 1,
            strong=True,
        )
        if completion[0] is False:
            return completion
        if completion[0] is None:
            return (None, close_row['edge'], 'ena returned high, but command completion was not observed in the trace')

    return (True, None, 'with the requirement stated as “ena gates normal timing and input-filter operation”, cmd_ack stayed inactive while ena was low and completion resumed after ena returned high')

from specflow.refmodel.temporal import WHILE_ACTIVE, after, throughout


def decide(trace):
    def in_value(row, port, value):
        return row['inputs'].get(port) == value

    def out_value(row, port, value):
        return row['outputs'].get(port) == value

    def paused_write(row):
        return (
            in_value(row, 'ena', 0)
            and in_value(row, 'rst', 0)
            and in_value(row, 'nReset', 1)
            and out_value(row, 'write_sequence', 1)
            and out_value(row, 'al', 0)
            and out_value(row, 'slave_wait', 0)
        )

    windows = after(trace, paused_write, until=WHILE_ACTIVE)
    if not windows:
        return (None, None, 'no already-accepted WRITE was observed while ena was low')

    resumed = False
    for window in windows:
        paused = throughout(
            window,
            lambda row: out_value(row, 'cmd_ack', 0)
        )
        if paused[0] is False:
            return paused
        if paused[0] is None:
            continue

        last_index = window.rows[-1]['index'] if window.rows else None
        if last_index is None:
            continue
        next_index = last_index + 1
        if next_index >= len(trace):
            continue

        row = trace[next_index]
        if not (
            in_value(row, 'ena', 1)
            and in_value(row, 'rst', 0)
            and in_value(row, 'nReset', 1)
            and out_value(row, 'al', 0)
            and out_value(row, 'slave_wait', 0)
        ):
            continue

        saw_active_resume = False
        for later in trace[next_index:]:
            if in_value(later, 'rst', 1) or in_value(later, 'nReset', 0):
                break
            if out_value(later, 'al', 1) or out_value(later, 'slave_wait', 1):
                break
            if out_value(later, 'write_sequence', 1):
                saw_active_resume = True
            if out_value(later, 'cmd_ack', 1):
                resumed = True
                break
            if saw_active_resume and out_value(later, 'write_sequence', 0):
                return (
                    False,
                    later['edge'],
                    'after ena was re-enabled, the WRITE ended without the routed cmd_ack completion'
                )
        if resumed:
            break

    if not resumed:
        return (
            None,
            None,
            'ena-low behavior was observed, but the trace did not also show the same WRITE resuming without reset, arbitration loss, or SCL stretching'
        )
    return (
        True,
        None,
        'cmd_ack was absent throughout the ena-low WRITE window and appeared only after ena was re-enabled'
    )

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, worst

    def probe(row, name):
        return row['outputs'].get(name) == 1

    starts = []
    for i, row in enumerate(trace):
        active = probe(row, 'fsm_active')
        was_active = (probe(trace[i - 1], 'fsm_active') if i else False)
        if active and not was_active and row['inputs'].get('ena') == 1:
            starts.append(i)

    verdicts = []
    for start in starts:
        def applies(row, start=start):
            return row is trace[start]

        def closes(row):
            return not probe(row, 'fsm_active')

        def aborts(row):
            return (row['inputs'].get('nReset') == 0 or
                    row['inputs'].get('rst') == 1 or
                    probe(row, 'al') or
                    probe(row, 'slave_wait') or
                    probe(row, 'scl_sync'))

        windows = after(trace, applies, until=closes, aborts=aborts)
        verdicts.extend(
            eventually(
                window,
                lambda row: row['outputs'].get('cmd_ack') == 1,
                strong=False,
                after_activation=False)
            for window in windows)

    if not verdicts:
        return (None, None, 'no enabled command transaction exercised clk_cnt pacing')
    return worst(verdicts)

def decide(trace):
    reached = [
        r for r in trace
        if r.get('outputs', {}).get('filter_cnt') == 1
    ]
    if not reached:
        return (None, None,
                'filter_cnt was never reached; the filter-sampling situation did not occur in this trace')
    return (True, reached[0].get('edge'),
            'filter_cnt was reached, as required by the stated filter-interval derivation')

def decide(trace):
    phase_rows = []
    for row in trace:
        outputs = row.get('outputs', {})
        inputs = row.get('inputs', {})
        if outputs.get('write_high_phase') == 1 and 'sda_oen' in outputs and 'din' in inputs:
            phase_rows.append(row)

    if not phase_rows:
        return (None, None, 'WRITE high phase was not observed; the command was not exercised')

    for row in phase_rows:
        expected = 0 if row['inputs']['din'] == 0 else 1
        if row['outputs']['sda_oen'] != expected:
            return (
                False,
                row.get('edge'),
                f"during the WRITE high phase, sda_oen was {row['outputs']['sda_oen']} for din={row['inputs']['din']}; expected {expected}"
            )

    return (
        True,
        phase_rows[0].get('edge'),
        'during the observed WRITE high phase, sda_oen matched din: 0 drives SDA low and 1 releases SDA'
    )

from specflow.refmodel.temporal import after, throughout, worst


def decide(trace):
    unsupported_or_idle = {
        0, 3, 5, 6, 7, 9, 10, 11, 12, 13, 14, 15
    }

    def decode(row):
        return (
            row['inputs']['ena'] == 1
            and row['inputs']['cmd'] in unsupported_or_idle
        )

    def idle_decode(row):
        return decode(row) and row['outputs']['fsm_active'] == 0

    windows = after(
        trace,
        idle_decode,
        until=lambda row: not decode(row),
    )

    return worst([
        throughout(
            window,
            lambda row: row['outputs']['fsm_active'] == 0,
            after_activation=False,
        )
        for window in windows
    ])

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, throughout, worst

    def holds(cond):
        return lambda row: all(
            row['outputs'].get(port, row['inputs'].get(port)) == value
            for port, value in cond.items()
        )

    def any_condition(alternatives):
        predicates = [holds(condition) for condition in alternatives]
        return lambda row: any(predicate(row) for predicate in predicates)

    opens = lambda row: (
        row['inputs'].get('ena') == 1
        and row['outputs'].get('write_sequence') == 1
    )
    aborts = any_condition([
        {'al': 1},
        {'nReset': 0},
        {'rst': 1},
    ])
    windows = after(
        trace,
        opens,
        until=holds({'cmd_ack': 1}),
        aborts=aborts,
    )

    def transmitted_bit(row):
        din = row['inputs'].get('din')
        return row['outputs'].get('sda_oen') == din

    return worst([
        throughout(window, transmitted_bit, after_activation=True)
        for window in windows
    ])

from specflow.refmodel.temporal import after, eventually, worst

def decide(trace):
    def value(row, port):
        return row['outputs'].get(port, row['inputs'].get(port))

    def write_active(row):
        return (
            value(row, 'write_sequence') == 1
            and row['inputs'].get('ena') == 1
            and row['inputs'].get('din') in (0, 1)
        )

    def aborted(row):
        return (
            value(row, 'al') == 1
            or row['inputs'].get('nReset') == 0
            or row['inputs'].get('rst') == 1
        )

    windows = after(
        trace,
        write_active,
        until=lambda row: value(row, 'cmd_ack') == 1,
        aborts=aborted,
    )

    follows = True

    def required_level(window):
        expected = 0 if window.value('din') == 0 else 1
        return lambda row: value(row, 'sda_oen') == expected

    return worst([
        eventually(
            window,
            required_level(window),
            strong=False,
            after_activation=follows,
        )
        for window in windows
    ])

def decide(trace):
    from specflow.refmodel.temporal import WHILE_ACTIVE, after, throughout, worst

    def out(row, name, default=None):
        return row.get('outputs', {}).get(name, default)

    def inp(row, name, default=None):
        return row.get('inputs', {}).get(name, default)

    # The declared read_window probe identifies the READ sample situation;
    # its extent, rather than a command value or fixed edge count, scopes this
    # clock-stretching check.
    windows = after(
        trace,
        lambda r: out(r, 'read_window') == 1,
        until=WHILE_ACTIVE
    )

    checks = []
    for w in windows:
        stretched = [r for r in w.rows if inp(r, 'scl_i') == 0]
        if not stretched:
            continue
        checks.append(
            throughout(
                w,
                lambda r: inp(r, 'scl_i') != 0 or out(r, 'scl_oen') == 1
            )
        )

    return worst(checks)

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def inp(row, name):
        return row.get('inputs', {}).get(name)

    def reset_active(row):
        return inp(row, 'nReset') == 0 or inp(row, 'rst') == 1

    def activation_rows(probe):
        rows = []
        previous = 0
        for i, row in enumerate(trace):
            active = (out(row, probe) == 1 and inp(row, 'ena') == 1
                      and not reset_active(row))
            if active and not previous:
                rows.append(i)
            previous = 1 if active else 0
        return rows

    def required_transition(start, rising):
        previous_busy = None
        for i in range(start, len(trace)):
            row = trace[i]
            if reset_active(row):
                return None, 'aborted by reset'
            busy = out(row, 'busy')
            if i > 0:
                previous_busy = out(trace[i - 1], 'busy')
            if rising:
                if busy == 1 and previous_busy == 0:
                    return row.get('edge'), None
            else:
                if busy == 0 and previous_busy == 1:
                    return row.get('edge'), None
        return None, 'the required busy transition was not observed'

    starts = activation_rows('sta_condition')
    stops = activation_rows('sto_condition')
    if not starts and not stops:
        return (None, None, 'no enabled filtered SDA START or STOP condition occurred')

    failures = []
    passed = []
    for i in starts:
        edge, reason = required_transition(i, True)
        if reason == 'aborted by reset':
            continue
        if edge is None:
            failures.append((trace[i].get('edge'), 'busy did not rise after the filtered START condition'))
        else:
            passed.append(edge)

    for i in stops:
        edge, reason = required_transition(i, False)
        if reason == 'aborted by reset':
            continue
        if edge is None:
            failures.append((trace[i].get('edge'), 'busy did not fall after the filtered STOP condition'))
        else:
            passed.append(edge)

    if failures:
        edge, detail = failures[0]
        return (False, edge, detail)

    if not starts or not stops:
        return (None, None, 'only one of the START and STOP routed observation cases occurred')

    return (True, passed[-1] if passed else None, 'busy rose after START and fell after STOP')

def decide(trace):
    def inp(row, name):
        return row.get('inputs', {}).get(name)

    def out(row, name):
        return row.get('outputs', {}).get(name)

    def reset(row):
        return inp(row, 'nReset') == 0 or inp(row, 'rst') == 1

    observed = ('busy', 'al', 'dout')
    pending_sda_transition = False
    witnessed = False

    for i, row in enumerate(trace):
        prev = trace[i - 1] if i else None

        if reset(row):
            pending_sda_transition = False
            continue

        if inp(row, 'ena') != 1:
            pending_sda_transition = False
            continue

        sampled = out(row, 'filter_sample_update') == 1

        if prev is not None and not reset(prev) and inp(prev, 'ena') == 1:
            if inp(prev, 'sda_i') != inp(row, 'sda_i'):
                pending_sda_transition = True

        # A filter update is the declared evidence that the synchronized
        # sample has entered the filtering process.  Same-state evidence is
        # allowed because no exact registered-output latency is specified.
        if sampled:
            pending_sda_transition = False

        if prev is None or reset(prev) or inp(prev, 'ena') != 1:
            continue

        changed = [name for name in observed
                   if out(prev, name) != out(row, name)]
        if not changed:
            continue

        if pending_sda_transition:
            return (False, row.get('edge'),
                    'observable SDA use changed %s before sda_i had a synchronized and filtered sample' %
                    ', '.join(changed))

        if sampled or out(prev, 'filter_sample_update') == 1:
            witnessed = True

    if not witnessed:
        return (None, None,
                'no enabled busy, al, or dout change was observed after declared SDA filtering activity')

    return (True, None,
            'enabled observable SDA effects were not produced before synchronized and filtered sampling')

def decide(trace):
    from specflow.refmodel.temporal import after, edges, eventually, worst

    def inp(row, name, default=0):
        return row.get('inputs', {}).get(name, default)

    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    terminal_edges = set()
    for probe in ('start_sequence', 'stop_sequence',
                  'read_sequence', 'write_sequence'):
        terminal_edges.update(edges(trace, probe, 'fall'))

    def completes(row):
        return (row.get('edge') in terminal_edges and
                inp(row, 'ena') == 1 and
                inp(row, 'nReset') != 0 and
                inp(row, 'rst') != 1 and
                out(row, 'al') != 1)

    def aborts(row):
        return (inp(row, 'nReset') == 0 or
                inp(row, 'rst') == 1 or
                out(row, 'al') == 1)

    # The acknowledge closes the transaction; no latency or edge count is
    # imposed beyond the duration explicitly stated by the obligation.
    windows = after(
        trace,
        completes,
        until=lambda r: out(r, 'cmd_ack') == 1,
        aborts=aborts,
        overlap=True,
    )

    def check(w):
        verdict = eventually(
            w,
            lambda r: out(r, 'cmd_ack') == 1,
            strong=True,
            after_activation=False,
        )
        if verdict[0] is not True:
            return verdict

        rows = w.rows
        first = None
        for i, row in enumerate(rows):
            if out(row, 'cmd_ack') == 1:
                first = i
                break

        if first is None:
            return (False, w.edge, 'cmd_ack was not high at command completion')

        width = 0
        j = first
        while j < len(rows) and out(rows[j], 'cmd_ack') == 1:
            width += rows[j].get('held', 1)
            j += 1

        if width != 1:
            return (
                False,
                rows[first].get('edge'),
                f'cmd_ack was asserted for {width} clock cycle(s), expected exactly one clock cycle',
            )

        return (
            True,
            rows[first].get('edge'),
            'cmd_ack was asserted for exactly one clock cycle at command completion',
        )

    return worst([check(w) for w in windows])

