                return (False, trace[premature_ack]['edge'],
                        'cmd_ack asserted before the active command finished')
            return (None, None,
                    'the supported command did not finish before the trace ended')

        if premature_ack is not None:
            return (False, trace[premature_ack]['edge'],
                    'cmd_ack asserted before the active command finished')

        high_edges = 0
        k = finish
        while k < len(trace) and out(trace[k], 'cmd_ack') == 1:
