def decide(trace):
    def out(row, name, default=None):
        return row['outputs'].get(name, default)

    sda_fall = edges(trace, 'sda_i', 'fall')
    sda_rise = edges(trace, 'sda_i', 'rise')
    scl_rise = edges(trace, 'scl_i', 'rise')
    scl_fall = edges(trace, 'scl_i', 'fall')

    # A filtered START aborts this short-glitch window: from that point the
    # ordinary START/busy requirement, not this requirement, owns the effect.
    sda_windows = after(
        trace,
        lambda r: r['edge'] in sda_fall
        and out(r, 'fscl') == 1
        and not out(r, 'fsm_active', 0),
        until=lambda r: r['edge'] in sda_rise,
        aborts=lambda r: bool(out(r, 'sta_condition', 0)),
    )

    # A filtered SCL rising edge means this was not a short, filter-rejected
    # SCL glitch; the linked dout requirement owns that case instead.
    scl_windows = after(
        trace,
        lambda r: r['edge'] in scl_rise
        and r['inputs'].get('ena') == 1
        and out(r, 'fscl') == 0,
        until=lambda r: r['edge'] in scl_fall,
        aborts=lambda r: bool(out(r, 'filtered_scl_rise', 0)),
    )

    verdicts = []
    verdicts.extend(
        throughout(
            w,
            lambda r: out(r, 'busy') == 0,
            after_activation=False,
        )
        for w in sda_windows
    )
    verdicts.extend(
        stable(w, 'dout', after_activation=False)
        for w in scl_windows
    )

    # The routed observation must distinguish this requirement's quiet case
    # from a design that never performs the linked ordinary behavior at all.
    ordinary_busy = any(
        out(trace[j], 'sta_condition', 0)
        and any(out(trace[k], 'busy') == 1 for k in range(j + 1, len(trace)))
        for j in range(len(trace))
    )
    dout_changes = set(edges(trace, 'dout', 'change'))
    ordinary_dout = any(
        out(row, 'filtered_scl_rise', 0)
        and any(trace[k]['edge'] in dout_changes for k in range(i + 1, len(trace)))
        for i, row in enumerate(trace)
    )

    result = worst(verdicts)
    if result[0] is False:
        return result
    if sda_windows and not ordinary_busy:
        return (None, None, 'short SDA glitch was observed, but no ordinary START-to-busy behavior was observed')
    if scl_windows and not ordinary_dout:
        return (None, None, 'short SCL glitch was observed, but no ordinary filtered-SCL-to-dout behavior was observed')
    if not sda_windows and not scl_windows:
        return (None, None, 'no short SDA or SCL glitch activation occurred')
    if not ordinary_busy and not ordinary_dout:
        return (None, None, 'only the no-effect side of the routed observations was present')
    return result

