from specflow.refmodel.temporal import TO_END, after, edges, eventually, worst


def _out(row, port):
    return row.get("outputs", {}).get(port)


def _probe(row, port):
    return _out(row, port) == 1


def decide(trace):
    aborts = lambda row: (
        _out(row, "al") == 1
        or row.get("inputs", {}).get("nReset") == 0
        or row.get("inputs", {}).get("rst") == 1
    )

    terminal_events = [
        ("start_sequence", "scl_oen", "fall", "START"),
        ("stop_sequence", "sda_oen", "rise", "STOP"),
        ("read_sequence", "scl_oen", "fall", "READ"),
        ("write_sequence", "scl_oen", "fall", "WRITE"),
    ]

    verdicts = []
    for sequence, port, direction, name in terminal_events:
        event_edges = edges(trace, port, direction)
        windows = after(
            trace,
            lambda row, event_edges=event_edges, sequence=sequence:
                row.get("edge") in event_edges and _probe(row, sequence),
            until=TO_END,
            aborts=aborts,
            overlap=True,
        )

        for window in windows:
            response = eventually(
                window,
                lambda row: _out(row, "cmd_ack") == 1,
                strong=True,
                after_activation=True,
            )
            if response[0] is not True:
                verdicts.append(response)
                continue

            ack_index = None
            for i, row in enumerate(window.rows):
                if _out(row, "cmd_ack") == 1:
                    ack_index = i
                    break

            if ack_index is None:
                verdicts.append((None, window.edge,
                                 f"{name} terminal phase was observed, but the cmd_ack response is not fully observable"))
                continue

            ack_row = window.rows[ack_index]
            high_edges = 0
            ended = False
            for row in window.rows[ack_index:]:
                if _out(row, "cmd_ack") != 1:
                    ended = True
                    break
                high_edges += row.get("held", 1)

            if high_edges != 1:
                verdicts.append((False, ack_row.get("edge"),
                                 f"cmd_ack was high for {high_edges} clk cycle(s) after the {name} sequence; expected exactly one clk cycle"))
            elif not ended:
                verdicts.append((None, ack_row.get("edge"),
                                 f"cmd_ack was high for one observed clk cycle after the {name} sequence, but its falling edge is outside the trace"))
            else:
                verdicts.append((True, ack_row.get("edge"),
                                 f"cmd_ack was asserted for exactly one clk cycle at the end of the {name} sequence"))

    return worst(verdicts)

def decide(trace):
    sequence_ports = (
        "start_sequence",
        "stop_sequence",
        "read_sequence",
        "write_sequence",
    )

    terminal_edges = set()
    for port in sequence_ports:
        previous = None
        for row in trace:
            value = row["outputs"].get(port)
            if previous == 1 and value != 1:
                terminal_edges.add(row["edge"])
            previous = value

    candidates = []
    for i, row in enumerate(trace):
        if row["edge"] not in terminal_edges:
            continue
        inputs = row["inputs"]
        outputs = row["outputs"]
        if inputs.get("nReset") == 0 or inputs.get("rst") == 1:
            continue
        if outputs.get("al") == 1:
            continue
        candidates.append(i)

    if not candidates:
        return (None, None, "no START, STOP, READ, or WRITE sequence reached its terminal phase")

    for terminal_i in candidates:
        terminal = trace[terminal_i]
        start_i = terminal_i
        for j in range(terminal_i - 1, -1, -1):
            if any(
                trace[j]["outputs"].get(p) == 1
                and trace[j - 1]["outputs"].get(p) != 1
                for p in sequence_ports
            ):
                start_i = j
                break

        early_ack = any(
            trace[j]["outputs"].get("cmd_ack") == 1
            for j in range(start_i, terminal_i)
        )
        if early_ack:
            return (False, terminal["edge"], "cmd_ack asserted before the sequence terminal phase")

        ack_i = None
        for j in range(terminal_i, len(trace)):
            if trace[j]["outputs"].get("cmd_ack") == 1:
                ack_i = j
                break

        if ack_i is None:
            return (False, terminal["edge"], "the completed bit-level operation produced no cmd_ack pulse")

        if ack_i > 0 and trace[ack_i - 1]["outputs"].get("cmd_ack") == 1:
            return (False, trace[ack_i]["edge"], "cmd_ack was already asserted rather than pulsing at completion")

        width = 0
        j = ack_i
        while j < len(trace) and trace[j]["outputs"].get("cmd_ack") == 1:
            width += trace[j].get("held", 1)
            j += 1

        if width != 1:
            return (False, trace[ack_i]["edge"], f"cmd_ack was asserted for {width} clock edge(s), expected exactly one")

        return (True, trace[ack_i]["edge"], "cmd_ack asserted for exactly one clock edge after sequence completion")

    return (None, None, "all observed sequence terminals were reset or aborted")

