def decide(trace):
    observable = ('cmd_ack', 'busy', 'al', 'dout', 'scl_oen', 'sda_oen')
    exposed = any(all(port in row.get('outputs', {}) for port in observable)
                  for row in trace)
    if not exposed:
        return (None, None, 'declared observable ports are not exposed in this trace')
    return (None, None, 'REQ-0002 is a capability summary without a single licensed output effect; cmd_ack, busy, al, dout, scl_oen, and sda_oen were observed but no sound assertion can be formed')

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def probe(row, name):
        return out(row, name)

    def ordered(rows, states):
        pos = 0
        for row in rows:
            if pos < len(states) and all(out(row, p) == v for p, v in states[pos].items()):
                pos += 1
        return pos == len(states)

    def phase_rows(name, start):
        rows = []
        for row in trace[start:]:
            if probe(row, name):
                rows.append(row)
            elif rows:
                break
        return rows

    def command_result(start, phase):
        active_seen = False
        for row in trace[start:]:
            if probe(row, 'al'):
                return True, row['edge'], 'arbitration loss legitimately aborted the active command'
            if out(row, 'cmd_ack') == 1:
                return True, row['edge'], 'supported command reached completion and asserted cmd_ack'
            if probe(row, 'fsm_active'):
                active_seen = True
            elif active_seen:
                return False, row['edge'], 'supported command phase ended without cmd_ack'
        return None, None, 'the supported command transaction did not finish in this trace'

    def check_command(phase, states, label, din_value=None):
        for i, row in enumerate(trace):
            if not probe(row, phase):
                continue
            rows = phase_rows(phase, i)
            if din_value is not None and row.get('inputs', {}).get('din') != din_value:
                continue
            if not rows:
                continue
            if not ordered(rows, states):
                return False, rows[0]['edge'], label + ' did not show the required ordered output-enable phases'
            result = command_result(i, phase)
            if result[0] is False:
                return result
            if result[0] is True:
                return result
            return None, None, label + ' was started but the transaction was incomplete'
        return None, None, label + ' was not exercised in this trace'

    results = []
    results.append(check_command(
        'start_sequence',
        [
            {'scl_oen': 1, 'sda_oen': 1},
            {'scl_oen': 1, 'sda_oen': 0},
            {'scl_oen': 0}
        ],
        'START generation'))
    results.append(check_command(
        'stop_sequence',
        [
            {'sda_oen': 0},
            {'scl_oen': 1},
            {'sda_oen': 1}
        ],
        'STOP generation'))

    for i, row in enumerate(trace):
        if not probe(row, 'write_sequence'):
            continue
        din = row.get('inputs', {}).get('din')
        expected_sda = 0 if din == 0 else 1
        rows = phase_rows('write_sequence', i)
        if not any(out(r, 'sda_oen') == expected_sda for r in rows):
            results.append((False, row['edge'], 'WRITE did not drive or release SDA according to din'))
        elif not ordered(rows, [{'scl_oen': 1}, {'scl_oen': 0}]):
            results.append((False, row['edge'], 'WRITE did not release SCL and then pull it low'))
        else:
            results.append(command_result(i, 'write_sequence'))
        break

    results.append(check_command(
        'read_sequence',
        [{'sda_oen': 1}, {'scl_oen': 1}],
        'READ generation'))

    rise_seen = False
    stop_seen = False
    for i, row in enumerate(trace):
        if probe(row, 'sta_condition'):
            rise_seen = True
            for later in trace[i + 1:]:
                if out(later, 'busy') == 1:
                    break
            else:
                results.append((False, row['edge'], 'busy did not rise after the filtered START condition'))
        if probe(row, 'sto_condition'):
            stop_seen = True
            for later in trace[i + 1:]:
                if out(later, 'busy') == 0:
                    break
            else:
                results.append((False, row['edge'], 'busy did not clear after the filtered STOP condition'))

    for i, row in enumerate(trace):
        if probe(row, 'slave_wait'):
            rows = phase_rows('slave_wait', i)
            if rows and any(out(r, 'scl_oen') != 1 for r in rows):
                results.append((False, rows[0]['edge'], 'SCL was not kept released during slave clock stretching'))
            break

    for i, row in enumerate(trace):
        if probe(row, 'scl_sync'):
            if not any(out(r, 'scl_oen') == 1 for r in trace[i:]):
                results.append((False, row['edge'], 'SCL was not released during multi-master synchronization'))
            break

    for i, row in enumerate(trace):
        if probe(row, 'write_high_phase') and row.get('inputs', {}).get('din') == 1 and row.get('inputs', {}).get('sda_i') == 0:
            if not any(out(r, 'al') == 1 for r in trace[i:]):
                results.append((False, row['edge'], 'arbitration loss was not detected during released-high WRITE arbitration'))
            break

    for i, row in enumerate(trace):
        if probe(row, 'filtered_scl_rise') and probe(row, 'read_window'):
            fsda = probe(row, 'fsda')
            if fsda is not None and not any(out(r, 'dout') == fsda for r in trace[i:]):
                results.append((False, row['edge'], 'READ did not capture the filtered SDA value'))
            break

    failures = [r for r in results if r[0] is False]
    if failures:
        return failures[0]
    decided = [r for r in results if r[0] is True]
    if decided:
        return True, decided[0][1], 'the exercised command or bus capability showed its required observable behavior'
    if rise_seen or stop_seen:
        return None, None, 'filtered bus activity was observed but its transaction was incomplete'
    return None, None, 'none of the supported command or filtered bus capability windows occurred in this trace'

def decide(trace):
    from specflow.refmodel.temporal import TO_END, WHILE_ACTIVE, after, edges, eventually, throughout, worst

    def out(row, name):
        return row.get('outputs', {}).get(name)

    def inp(row, name):
        return row.get('inputs', {}).get(name)

    def reset(row):
        return inp(row, 'rst') == 1 or inp(row, 'nReset') == 0

    def command_windows(probe, abort_loss=False):
        return after(
            trace,
            lambda r: inp(r, 'ena') == 1 and out(r, probe) == 1,
            until=TO_END,
            aborts=(lambda r: reset(r) or (abort_loss and out(r, 'al') == 1))
        )

