def decide(trace):
    # The physical SCL/SDA line response is external to this requirement's
    # observable ports. scl_i and sda_i are stimulus inputs, not DUT effects,
    # and scl_oen/sda_oen alone cannot distinguish the required line behavior
    # from merely repeating the activation.
    seen_update = False
    previous = None
    for row in trace:
        values = (row['outputs'].get('scl_oen'), row['outputs'].get('sda_oen'))
        if previous is not None and values != previous:
            seen_update = True
        previous = values
    if seen_update:
        return (None, None, 'the physical SCL/SDA response is external and is not observable without duplicating REQ-0003 or checking input stimulus')
    return (None, None, 'the physical SCL/SDA response is not observable in this trace')

def decide(trace):
    transitions = []
    for i in range(1, len(trace)):
        before = trace[i - 1].get('outputs', {})
        after = trace[i].get('outputs', {})
        for port in ('scl_oen', 'sda_oen'):
            old = before.get(port)
            new = after.get(port)
            if old != new and new in (0, 1):
                transitions.append((trace[i], port, new))

    if not transitions:
        return (None, None, 'no scl_oen or sda_oen drive/release transition occurred in this trace')

    ports = sorted(set(port for _, port, _ in transitions))
    values = sorted(set(value for _, _, value in transitions))
    return (True, transitions[0][0].get('edge'),
            f'output-enable transition(s) observed on {", ".join(ports)} into value(s) {values}; the resolved external line is not a declared observable')

