def decide(trace):
    sequence_ports = [
        "start_sequence",
        "stop_sequence",
        "read_sequence",
        "write_sequence",
    ]

    verdicts = []
    for sequence in sequence_ports:
        rows = []
        for row in trace:
            active = row["outputs"].get(sequence) == 1
            if active:
                rows.append(row)
            elif rows:
                break

        if not rows:
            continue

        first = rows[0]
        start_index = trace.index(first)
        baseline = None
        if start_index > 0:
            prior = trace[start_index - 1]["outputs"]
            baseline = {
                "scl_oen": prior.get("scl_oen"),
                "sda_oen": prior.get("sda_oen"),
            }

        changed = {
            "scl_oen": False,
            "sda_oen": False,
        }
        for row in rows:
            outputs = row["outputs"]
            for port in changed:
                if baseline is not None and outputs.get(port) != baseline[port]:
                    changed[port] = True
            if len(rows) > 1:
                previous = rows[rows.index(row) - 1]["outputs"] if rows.index(row) > 0 else None
                if previous is not None:
                    for port in changed:
                        if outputs.get(port) != previous.get(port):
                            changed[port] = True

        if not changed["scl_oen"] or not changed["sda_oen"]:
            missing = [port for port, did_change in changed.items() if not did_change]
            verdicts.append((False, first["edge"],
                             f"{sequence} produced no observable bit-level change on {', '.join(missing)}"))
        else:
            verdicts.append((True, None,
                             f"{sequence} generated observable bit-level activity on scl_oen and sda_oen"))

    if not verdicts:
        return (None, None, "no declared START, STOP, READ, or WRITE sequence occurred in this trace")

    for verdict in verdicts:
        if verdict[0] is False:
            return verdict
    return (True, None, "each exercised command sequence generated activity on scl_oen and sda_oen")

