def decide(trace):
    observable = (
        'cmd_ack', 'busy', 'al', 'dout', 'scl_oen', 'sda_oen'
    )

    active = []
    for row in trace:
        outputs = row.get('outputs', {})
        if outputs.get('fsm_active') == 1:
            active.append(row)

    if not active:
        return (None, None,
                'fsm_active never became asserted; no synchronous-update state was exercised')

    previous = None
    for row in trace:
        if row['index'] < active[0]['index']:
            continue

        held = row.get('held')
        if not isinstance(held, int) or held < 1:
            return (False, row.get('edge'),
                    'a sampled state has no positive held duration')

        outputs = row.get('outputs', {})
        missing = [port for port in observable if port not in outputs]
        if missing:
            return (False, row.get('edge'),
                    f'observable registered output(s) missing from trace: {missing}')

        if previous is not None:
            expected_edge = previous.get('edge') + previous.get('held')
            if row.get('edge') != expected_edge:
                return (False, row.get('edge'),
                        'observable output state changed away from a recorded rising-edge boundary')

        previous = row

    return (True, active[0].get('edge'),
            'observable registered outputs are stable for each held state and changes occur only at recorded rising-edge state boundaries')

def decide(trace):
    observable = (
        'cmd_ack', 'busy', 'al', 'dout', 'scl_oen', 'sda_oen'
    )

    if not trace:
        return (None, None, 'no sampled synchronous states were present in the trace')

    for row in trace:
        outputs = row.get('outputs', {})
        missing = [port for port in observable if port not in outputs]
        if missing:
            return (False, row.get('edge'),
                    f'observable registered output(s) missing from trace: {missing}')
        held = row.get('held')
        if not isinstance(held, int) or held < 1:
            return (False, row.get('edge'),
                    'a sampled output state has no positive held duration')

    for previous, current in zip(trace, trace[1:]):
        previous_outputs = previous['outputs']
        current_outputs = current['outputs']
        changed = [
            port for port in observable
            if previous_outputs[port] != current_outputs[port]
        ]
        if not changed:
            continue

        expected_edge = previous['edge'] + previous['held']
        if current['edge'] != expected_edge:
            return (False, current.get('edge'),
                    f'{changed} changed to a new value between rising-edge update boundaries')

    return (True, trace[0].get('edge'),
            'all observable registered outputs remain stable for each held state and change only at rising-edge boundaries')

