    def out(row, name):
        return row.get('outputs', {}).get(name)

    # fsm_active is the declared probe naming normal synchronous state-update
    # activity. Reset handling is also named by the routed observation.
    applicable = [
        r for r in trace
        if out(r, 'fsm_active') == 1
        or r.get('inputs', {}).get('rst') == 1
        or r.get('inputs', {}).get('nReset') == 0
    ]
