        return (None, None,
                'no synchronous-update or reset-handling state was observed')

    # Every trace row is sampled at a rising edge of clk. A change between
    # distinct rows therefore occurs at the first rising edge of the later
    # row; inter-edge changes are not observable in this trace representation.
    changes = []
