def decide(trace):
    fall_edges = set()
    previous_nreset = None
    for row in trace:
        value = row['inputs'].get('nReset')
        if previous_nreset == 1 and value == 0:
            fall_edges.add(row['edge'])
        previous_nreset = value

    applicable = False
    for i, row in enumerate(trace):
        if row['edge'] not in fall_edges or i == 0:
            continue

        previous = trace[i - 1]
        previous_scl_oen = previous['outputs'].get('scl_oen')
        current_scl_oen = row['outputs'].get('scl_oen')

        if previous_scl_oen == 1:
            continue

        applicable = True
        if current_scl_oen != 1:
            return (False, row['edge'],
                    'after nReset fell while scl_oen was not reset, '
                    'scl_oen did not asynchronously change to released value 1')

        return (True, row['edge'],
                'nReset fell while scl_oen was not reset and scl_oen changed '
                'asynchronously to released value 1')

    if not applicable:
        return (None, None,
                'no applicable nReset falling transition occurred while '
                'scl_oen was away from its reset value')

    return (None, None, 'no applicable asynchronous reset transition was observed')

def decide(trace):
    applicable = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        prev_nreset = prev['inputs'].get('nReset')
        nreset = row['inputs'].get('nReset')
        prev_scl_oen = prev['outputs'].get('scl_oen')
        scl_oen = row['outputs'].get('scl_oen')

        # The route applies only when reset falls while scl_oen is not
        # already at its reset-state released value.
        if prev_nreset == 1 and nreset == 0 and prev_scl_oen != 1:
            applicable.append((i, row))

    if not applicable:
        return (None, None, 'no applicable nReset fall while scl_oen was non-reset')

    for _, row in applicable:
        if row['outputs'].get('scl_oen') != 1:
            return (False, row['edge'], 'scl_oen did not become the released reset value 1 on the asynchronous nReset assertion')
        if row['outputs'].get('scl_oen') == trace[row['index'] - 1]['outputs'].get('scl_oen'):
            return (False, row['edge'], 'scl_oen did not change asynchronously to the released reset value 1 when nReset fell')

    return (True, applicable[-1][1]['edge'], 'scl_oen changed to released value 1 when nReset fell')

