def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, throughout

    def out(row, name, default=0):
        return row['outputs'].get(name, default)

    def inp(row, name, default=0):
        return row['inputs'].get(name, default)

    ena_falls = edges(trace, 'ena', 'fall')

    def applies(row):
        return (
            row['edge'] in ena_falls
            and inp(row, 'ena') == 0
            and inp(row, 'nReset') == 1
            and inp(row, 'rst') == 0
            and out(row, 'fsm_active') == 1
            and out(row, 'al') == 0
            and out(row, 'slave_wait') == 0
        )

    def aborted(row):
        return (
            inp(row, 'nReset') == 0
            or inp(row, 'rst') == 1
            or out(row, 'al') == 1
            or out(row, 'slave_wait') == 1
        )

    windows = after(
        trace,
        applies,
        until=lambda row: inp(row, 'ena') == 1,
        aborts=aborted,
    )

    if not windows:
        return (None, None, 'ena did not fall during an active command')

    for window in windows:
        quiet = throughout(
            window,
            lambda row: out(row, 'cmd_ack') == 0,
        )
        if quiet[0] is False:
            return quiet

        trigger_edge = window.edge
        close_row = None
        close_kind = None
        for row in trace:
            if row['edge'] <= trigger_edge:
                continue
            if inp(row, 'nReset') == 0 or inp(row, 'rst') == 1 or out(row, 'al') == 1 or out(row, 'slave_wait') == 1:
                close_row = row
                close_kind = 'aborted'
                break
            if inp(row, 'ena') == 1:
                close_row = row
                close_kind = 'resumed'
                break

        if close_kind != 'resumed':
            return (None, trigger_edge, 'ena remained low or the routed command was aborted before resumption')

        resumed = after(
            trace,
            lambda row, edge=close_row['edge']: row['edge'] == edge,
            until=TO_END,
            aborts=aborted,
        )
        completion = eventually(
            resumed[0],
            lambda row: out(row, 'cmd_ack') == 1,
            strong=True,
        )
        if completion[0] is False:
            return completion
        if completion[0] is None:
            return (None, close_row['edge'], 'ena returned high, but command completion was not observed in the trace')

    return (True, None, 'with the requirement stated as “ena gates normal timing and input-filter operation”, cmd_ack stayed inactive while ena was low and completion resumed after ena returned high')

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, never

    def out(row, name):
        return row['outputs'].get(name)

    def inp(row, name):
        return row['inputs'].get(name)

    fall_edges = edges(trace, 'ena', 'fall')
    rise_edges = edges(trace, 'ena', 'rise')

    def paused_command(row):
        return (
            inp(row, 'ena') == 0
            and row['edge'] in fall_edges
            and out(row, 'fsm_active') == 1
            and out(row, 'cmd_ack') == 0
            and inp(row, 'rst') != 1
            and inp(row, 'nReset') != 0
            and out(row, 'al') != 1
            and out(row, 'slave_wait') != 1
        )

    def voided(row):
        return (
            inp(row, 'rst') == 1
            or inp(row, 'nReset') == 0
            or out(row, 'al') == 1
            or out(row, 'slave_wait') == 1
        )

    windows = after(trace, paused_command, until=lambda r: inp(r, 'ena') == 1,
                    aborts=voided)
    if not windows:
        return (None, None, 'no active command was paused by ena going low')

    for window in windows:
        low_check = never(window, lambda r: out(r, 'cmd_ack') == 1)
        if low_check[0] is False:
            return (False, low_check[1],
                    'cmd_ack pulsed while ena was low; timing/filter operation was not gated')
        if low_check[0] is not True:
            continue

        activation_edge = window.edge
        close_index = None
        for i, row in enumerate(trace):
            if row['edge'] <= activation_edge:
                continue
            if voided(row):
                break
            if inp(row, 'ena') == 1:
                close_index = i
                break
        if close_index is None:
            continue

        resumed = after(
            trace[close_index:],
            lambda r: r['edge'] in rise_edges and inp(r, 'ena') == 1
            and out(r, 'fsm_active') == 1,
            until=TO_END,
            aborts=voided
        )
        for resumed_window in resumed:
            completion = eventually(
                resumed_window,
                lambda r: out(r, 'cmd_ack') == 1,
                strong=False
            )
            if completion[0] is True:
                return (True, completion[1],
                        'cmd_ack was absent while ena was low and appeared after ena returned high')

    return (None, None,
            'ena-low gating was observed, but the corresponding post-enable completion was not observed')

