from specflow.refmodel.temporal import after, eventually, edges, worst


def decide(trace):
    active_rises = edges(trace, "fsm_active", "rise")

    def row_value(row, port):
        return row["outputs"].get(port, row["inputs"].get(port))

    def active_command(row):
        return (
            row["edge"] in active_rises
            and row_value(row, "ena") == 1
            and row_value(row, "nReset") != 0
            and row_value(row, "rst") != 1
        )

    def command_ends(row):
        return (
            row_value(row, "fsm_active") != 1
            or row_value(row, "cmd_ack") == 1
        )

    def aborts(row):
        return (
            row_value(row, "nReset") == 0
            or row_value(row, "rst") == 1
            or row_value(row, "ena") != 1
            or row_value(row, "al") == 1
        )

    windows = after(trace, active_command, until=command_ends, aborts=aborts)
    return worst([
        eventually(
            w,
            lambda r: row_value(r, "cmd_ack") == 1,
            strong=True,
            after_activation=False,
        )
        for w in windows
    ])

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, worst

    def probe(row, name):
        return row['outputs'].get(name) == 1

    starts = []
    for i, row in enumerate(trace):
        active = probe(row, 'fsm_active')
        was_active = (probe(trace[i - 1], 'fsm_active') if i else False)
        if active and not was_active and row['inputs'].get('ena') == 1:
            starts.append(i)

    verdicts = []
    for start in starts:
        def applies(row, start=start):
            return row is trace[start]

        def closes(row):
            return not probe(row, 'fsm_active')

        def aborts(row):
            return (row['inputs'].get('nReset') == 0 or
                    row['inputs'].get('rst') == 1 or
                    probe(row, 'al') or
                    probe(row, 'slave_wait') or
                    probe(row, 'scl_sync'))

        windows = after(trace, applies, until=closes, aborts=aborts)
        verdicts.extend(
            eventually(
                window,
                lambda row: row['outputs'].get('cmd_ack') == 1,
                strong=False,
                after_activation=False)
            for window in windows)

    if not verdicts:
        return (None, None, 'no enabled command transaction exercised clk_cnt pacing')
    return worst(verdicts)

