def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, worst

    start_rises = edges(trace, "start_sequence", "rise")
    if not start_rises:
        return (None, None, "START-command signature never occurred; no decoded START sequence was observed")

    def active_start(row):
        return row["edge"] in start_rises

    def done(row):
        return row["outputs"].get("fsm_active") == 0

    windows = after(trace, active_start, until=done)
    sda_falls = edges(trace, "sda_oen", "fall")
    return worst([
        eventually(
            w,
            lambda row: row["edge"] in sda_falls and row["outputs"].get("sda_oen") == 0,
            after_activation=True,
            strong=True,
        )
        for w in windows
    ])

def decide(trace):
    def out(row, name, default=None):
        return row.get('outputs', {}).get(name, default)

    positives = []
    negatives = []

    # The declared START-sequence probe is the unambiguous situation
    # signature; do not use an unstated numeric cmd encoding.
    for i, row in enumerate(trace):
        active = out(row, 'start_sequence', 0) == 1
        prior = out(trace[i - 1], 'start_sequence', 0) if i else 0
        if active and prior != 1:
            found_fall = False
            for j in range(i + 1, len(trace)):
                cur = trace[j]
                if (out(cur, 'start_sequence', 0) == 1 and
                        out(cur, 'scl_oen') == 1 and
                        out(trace[j - 1], 'sda_oen') != 0 and
                        out(cur, 'sda_oen') == 0):
                    found_fall = True
                    positives.append((True, cur['edge'], 'sda_oen fell to 0 in the declared START sequence'))
                    break
                if out(cur, 'start_sequence', 0) != 1:
                    if found_fall:
                        break
                    if j == len(trace) - 1:
                        positives.append((None, None, 'START sequence began but the trace ended before its SDA signature'))
                    else:
                        positives.append((False, cur['edge'], 'START sequence ended without sda_oen falling to 0 while SCL was released'))
                    break
            else:
                positives.append((None, None, 'START sequence began but the trace ended before its SDA signature'))

    # For a command presentation that leaves the FSM idle, the routed
    # otherwise-case says sda_oen remains released.  This uses no command
    # number and does not classify any encoding.
    for i in range(1, len(trace)):
        row = trace[i]
        prev = trace[i - 1]
        if (out(row, 'fsm_active', 0) == 0 and
                out(prev, 'fsm_active', 0) == 0 and
                row.get('inputs', {}).get('cmd') != prev.get('inputs', {}).get('cmd')):
            saw_idle = False
            became_active = False
            for j in range(i, len(trace)):
                cur = trace[j]
                if out(cur, 'fsm_active', 0) == 1:
                    became_active = True
                    break
                saw_idle = True
                if out(cur, 'sda_oen') != 1:
                    negatives.append((False, cur['edge'], 'sda_oen was not released during the idle command-decode window'))
                    break
            if not negatives or negatives[-1][0] is not False:
                if not became_active and saw_idle:
                    negatives.append((True, row['edge'], 'sda_oen remained high while the command left the FSM idle'))

    results = positives + negatives
    if any(r[0] is False for r in results):
        return next(r for r in results if r[0] is False)
    if any(r[0] is True for r in results):
        return next(r for r in results if r[0] is True)
    return (None, None, 'no declared START or idle command-decode signature occurred in this trace')

def decide(trace):
    from specflow.refmodel.temporal import after, edges, eventually

    outputs = lambda r: r.get('outputs', {})
    starts = edges(trace, 'start_sequence', 'rise')

    # A START decode is evidenced by entering the declared START sequence.
    # The routed effect must then drive SDA low while SCL remains released.
    start_windows = after(
        trace,
        lambda r: r['edge'] in starts,
        until=lambda r: outputs(r).get('fsm_active') == 0,
    )
    saw_start = bool(start_windows)
    for window in start_windows:
        verdict = eventually(
            window,
            lambda r: outputs(r).get('sda_oen') == 0
            and outputs(r).get('scl_oen') == 1,
            after_activation=True,
            strong=True,
        )
        if verdict[0] is False:
            return verdict

    # An idle command-decode observation with no subsequent START-sequence
    # signature supplies the contrasting ordinary behavior.  Do not classify
    # by a numeric command encoding.
    saw_idle_other = False
    for i, row in enumerate(trace):
        o = outputs(row)
        if o.get('fsm_active') != 0 or row.get('inputs', {}).get('ena') != 1:
            continue
        if o.get('sda_oen') != 1:
            continue
        cmd_changed = i == 0 or row.get('inputs', {}).get('cmd') != trace[i - 1].get('inputs', {}).get('cmd')
        if not cmd_changed:
            continue
        later_start = any(row2['edge'] > row['edge'] for row2 in trace if row2['edge'] in starts)
        if not later_start:
            saw_idle_other = True
            break

    if saw_start and saw_idle_other:
        edge = starts[0] if starts else None
        return (True, edge, 'START decode signature entered the START sequence and ordinary idle decode kept sda_oen released')
    return (None, None, 'the trace showed only one side of the routed START-decode distinction')

