def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def changed_at(port):
        result = set()
        for i in range(1, len(trace)):
            if out(trace[i], port) != out(trace[i - 1], port):
                result.add(i)
        return result

    scl_edges = changed_at('scl_i')
    sta_edges = changed_at('sta_condition')
    sto_edges = changed_at('sto_condition')
    filtered_events = sorted(
        [(i, 'START') for i in sta_edges if out(trace[i], 'sta_condition') == 1] +
        [(i, 'STOP') for i in sto_edges if out(trace[i], 'sto_condition') == 1]
    )

    filtered_seen = bool(filtered_events)
    raw_only_seen = False

    # A filtered START/STOP condition must produce the corresponding busy
    # transition.  Search states, not clock edges, so unspecified latency is
    # left open.
    for i, kind in filtered_events:
        expected = 1 if kind == 'START' else 0
        transition = None
        for j in range(i, len(trace)):
            if j == 0:
                continue
            previous = out(trace[j - 1], 'busy')
            current = out(trace[j], 'busy')
            if previous != current:
                transition = (j, previous, current)
                break
        if transition is None:
            return (False, trace[i].get('edge'),
                    'filtered %s condition occurred but busy never transitioned as required by the scl_i processing clause' % kind)
        j, previous, current = transition
        if current != expected:
            return (False, trace[j].get('edge'),
                    'filtered %s condition caused busy to transition to %s instead of %s' %
                    (kind, current, expected))

    # A raw SCL change that is not itself accompanied by a filtered START/STOP
    # must not alter busy before the next filtered condition.  This is the
    # observable signature of rejecting an unfiltered glitch.
    for i in sorted(scl_edges):
        if i in sta_edges or i in sto_edges:
            continue
        raw_only_seen = True
        next_filtered = [j for j, _ in filtered_events if j > i]
        stop = min(next_filtered) if next_filtered else len(trace)
        baseline = out(trace[i], 'busy')
        for j in range(i + 1, stop):
            if out(trace[j], 'busy') != baseline:
                return (False, trace[j].get('edge'),
                        'raw scl_i transition changed busy before any synchronized and filtered START/STOP condition')

    if not filtered_seen or not raw_only_seen:
        return (None, None,
                'trace shows only one side of the busy observable: both a filtered START/STOP event and a raw scl_i transition rejected by filtering are needed')

    return (True, None,
