def decide(trace):
    if not trace:
        return (None, None, 'no trace state is available for the declared SDA interface')

    def reset_active(row):
        inputs = row.get('inputs', {})
        return inputs.get('nReset') == 0 or inputs.get('rst') == 1

    events = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        if reset_active(row):
            continue
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        if inputs.get('ena') != 1 or outputs.get('fscl') != 1:
            continue
        old_sda = prev.get('outputs', {}).get('fsda')
        new_sda = outputs.get('fsda')
        if old_sda == 1 and new_sda == 0:
            events.append((i, 1, 'filtered high-to-low START transition'))
        elif old_sda == 0 and new_sda == 1:
            events.append((i, 0, 'filtered low-to-high STOP transition'))

    busy_changes = []
    for i in range(1, len(trace)):
        if reset_active(trace[i]):
            continue
        before = trace[i - 1].get('outputs', {}).get('busy')
        after = trace[i].get('outputs', {}).get('busy')
        if before in (0, 1) and after in (0, 1) and before != after:
            busy_changes.append((i, after))

    if not events:
        if busy_changes:
            i, value = busy_changes[0]
            return (False, trace[i].get('edge'),
                    'busy changed without a qualifying filtered SDA transition while enabled and SCL high')
        return (None, None, 'no qualifying filtered SDA transition occurred in this trace')

    for event_i, expected_busy, description in events:
        observed = False
        for j in range(event_i, len(trace)):
            if reset_active(trace[j]):
                break
            if trace[j].get('outputs', {}).get('busy') == expected_busy:
                observed = True
                break
        if not observed:
            return (False, trace[event_i].get('edge'),
                    f'{description} occurred, but busy did not reach {expected_busy}')

    for change_i, value in busy_changes:
        justified = any(event_i <= change_i and expected == value
                         for event_i, expected, _ in events)
        if not justified:
            return (False, trace[change_i].get('edge'),
                    'busy changed without the corresponding filtered SDA START/STOP signature')

    return (True, trace[events[0][0]].get('edge'),
            'busy response matches the qualifying filtered SDA START/STOP signatures')

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def inp(row, name):
        return row.get('inputs', {}).get(name)

    def reset_active(row):
        return inp(row, 'nReset') == 0 or inp(row, 'rst') == 1

    def activation_rows(probe):
        rows = []
        previous = 0
        for i, row in enumerate(trace):
            active = (out(row, probe) == 1 and inp(row, 'ena') == 1
                      and not reset_active(row))
            if active and not previous:
                rows.append(i)
            previous = 1 if active else 0
        return rows

    def required_transition(start, rising):
        previous_busy = None
        for i in range(start, len(trace)):
            row = trace[i]
            if reset_active(row):
                return None, 'aborted by reset'
            busy = out(row, 'busy')
            if i > 0:
                previous_busy = out(trace[i - 1], 'busy')
            if rising:
                if busy == 1 and previous_busy == 0:
                    return row.get('edge'), None
            else:
                if busy == 0 and previous_busy == 1:
                    return row.get('edge'), None
        return None, 'the required busy transition was not observed'

    starts = activation_rows('sta_condition')
    stops = activation_rows('sto_condition')
    if not starts and not stops:
        return (None, None, 'no enabled filtered SDA START or STOP condition occurred')

    failures = []
    passed = []
    for i in starts:
        edge, reason = required_transition(i, True)
        if reason == 'aborted by reset':
            continue
        if edge is None:
            failures.append((trace[i].get('edge'), 'busy did not rise after the filtered START condition'))
        else:
            passed.append(edge)

    for i in stops:
        edge, reason = required_transition(i, False)
        if reason == 'aborted by reset':
            continue
        if edge is None:
            failures.append((trace[i].get('edge'), 'busy did not fall after the filtered STOP condition'))
        else:
            passed.append(edge)

    if failures:
        edge, detail = failures[0]
        return (False, edge, detail)

    if not starts or not stops:
        return (None, None, 'only one of the START and STOP routed observation cases occurred')

    return (True, passed[-1] if passed else None, 'busy rose after START and fell after STOP')

