def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def reset(row):
        return row.get('inputs', {}).get('nReset') == 0 or row.get('inputs', {}).get('rst') == 1

    active = [i for i, row in enumerate(trace)
              if row.get('inputs', {}).get('ena') == 1 and not reset(row)]
    if not active:
        return (None, None, 'ena never remained high outside reset; SDA processing was not exercised')

    previous = None
    last_raw_sda_change = -1
    filter_updates = []
    sta_stop = []
    arbitration_checks = []
    filtered_rises = []
    effects = []

    for i, row in enumerate(trace):
        if reset(row):
            previous = row
            last_raw_sda_change = -1
            filter_updates = []
            sta_stop = []
            arbitration_checks = []
            filtered_rises = []
            continue

        if previous is not None:
            old_sda = previous.get('inputs', {}).get('sda_i')
            new_sda = row.get('inputs', {}).get('sda_i')
            if old_sda != new_sda:
                last_raw_sda_change = i

            if row.get('inputs', {}).get('ena') == 1:
                changed = []
                for port in ('busy', 'al', 'dout'):
                    if out(row, port) != out(previous, port):
                        changed.append(port)
                if changed:
                    effects.append((i, changed))

        if row.get('inputs', {}).get('ena') == 1:
            if out(row, 'filter_sample_update') == 1:
                filter_updates.append(i)
            if (out(row, 'sta_condition') == 1 or
                    out(row, 'sto_condition') == 1):
                sta_stop.append(i)
            if (out(row, 'sda_chk') == 1 or
                    out(row, 'write_high_phase') == 1):
                arbitration_checks.append(i)
            if (out(row, 'filtered_scl_rise') == 1 and
                    out(row, 'read_window') == 1):
                filtered_rises.append(i)

        previous = row

    if not effects:
        return (None, None, 'no enabled START/STOP, arbitration, or read-data effect occurred in this trace')

    for i, changed in effects:
        filtered_after_raw = [j for j in filter_updates
                              if last_raw_sda_change < j <= i]
        # Recompute the latest raw transition at the point of this effect.
        latest_raw = -1
        for k in range(1, i + 1):
            if trace[k].get('inputs', {}).get('sda_i') != trace[k - 1].get('inputs', {}).get('sda_i'):
                latest_raw = k
        filtered_after_raw = [j for j in filter_updates if latest_raw < j <= i]

        if 'busy' in changed:
            if not any(latest_raw < j <= i for j in sta_stop):
                return (False, trace[i].get('edge'),
                        'busy changed before a synchronized and filtered START/STOP transition')

        if 'al' in changed:
            if not filtered_after_raw:
                return (False, trace[i].get('edge'),
                        'al changed before sda_i had passed synchronization and filtering')
            if not any(latest_raw < j <= i for j in arbitration_checks + sta_stop):
                return (False, trace[i].get('edge'),
                        'al changed without a filtered arbitration-check or STOP indication')

        if 'dout' in changed:
            if not filtered_after_raw:
                return (False, trace[i].get('edge'),
                        'dout changed before sda_i had passed synchronization and filtering')
            if not any(latest_raw < j <= i for j in filtered_rises):
                return (False, trace[i].get('edge'),
                        'dout changed without a filtered SCL rising edge in the read window')

    return (True, None,
            'all exercised busy, al, and dout effects followed synchronized and filtered SDA processing')

def decide(trace):
    def inp(row, name, default=None):
        return row.get('inputs', {}).get(name, default)

    def out(row, name, default=None):
        return row.get('outputs', {}).get(name, default)

    def probe(row, name):
        return bool(out(row, name, 0))

    previous = None
    valid_seen = False
    observed = False
    start_seen = False
    stop_seen = False
    arbitration_seen = False
    sample_value = None
    read_was_active = False
    failures = []

    for row in trace:
        # The controller processes SDA only while enabled and out of reset.
        active = (inp(row, 'ena', 0) == 1 and
                  inp(row, 'rst', 0) == 0 and
                  inp(row, 'nReset', 1) == 1)
        if not active:
            previous = None
            start_seen = False
            stop_seen = False
            arbitration_seen = False
            sample_value = None
            read_was_active = False
            continue

        valid_seen = True
        busy = out(row, 'busy')
        al = out(row, 'al')
        dout = out(row, 'dout')

        # These probes are declared signatures of filtered SDA use.
        if probe(row, 'sta_condition'):
            start_seen = True
        if probe(row, 'sto_condition'):
            stop_seen = True

        # Arbitration evidence must use the filtered SDA value, not raw sda_i.
        if ((probe(row, 'sda_chk') or probe(row, 'write_high_phase')) and
                out(row, 'fsda') == 0):
            arbitration_seen = True
        if probe(row, 'sto_condition') and probe(row, 'fsm_active'):
            arbitration_seen = True

        # A read sample is licensed only by a filtered SCL rising edge, and
        # the captured value must be the filtered SDA value at that event.
        read_active = probe(row, 'read_sequence') or probe(row, 'read_window')
        if read_active and not read_was_active:
            sample_value = None
        if probe(row, 'filtered_scl_rise') and read_active:
            sample_value = out(row, 'fsda')

        if previous is not None:
            prev_busy, prev_al, prev_dout = previous

            if busy != prev_busy:
                observed = True
                if not (start_seen or stop_seen):
                    failures.append((row['edge'],
                                     'busy changed before a synchronized and filtered START/STOP condition'))

            if prev_al == 0 and al == 1:
                observed = True
                if not arbitration_seen:
                    failures.append((row['edge'],
                                     'al asserted before synchronized and filtered SDA arbitration evidence'))

            if dout != prev_dout:
                observed = True
                if sample_value is None:
                    failures.append((row['edge'],
                                     'dout changed without a preceding filtered SCL rising-edge sample'))
                elif dout != sample_value:
                    failures.append((row['edge'],
                                     'dout does not equal the synchronized and filtered SDA sample'))

        previous = (busy, al, dout)
        read_was_active = read_active

    if not valid_seen:
        return (None, None, 'ena never held high while out of reset; the SDA-processing situation did not occur')
    if not observed:
        return (None, None, 'no relevant busy, al, or dout transition occurred in the enabled, out-of-reset window')
    if failures:
        edge, detail = failures[0]
        return (False, edge, detail)
    return (True, None, 'all observed SDA effects followed declared synchronized and filtered evidence')

