def decide(trace):
    from specflow.refmodel.temporal import after, eventually, edges, worst

    def value(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def input_value(row, name, default=0):
        return row.get('inputs', {}).get(name, default)

    sequence_probes = (
        'start_sequence',
        'stop_sequence',
        'read_sequence',
        'write_sequence',
    )

    completion_edges = set()
    next_command_edges = set()
    for probe in sequence_probes:
        completion_edges.update(edges(trace, probe, 'fall'))
        next_command_edges.update(edges(trace, probe, 'rise'))

    def completes(row):
        return (row.get('edge') in completion_edges and
                input_value(row, 'ena') == 1)

    def starts_next_command(row):
        return row.get('edge') in next_command_edges

    def aborted(row):
        return (input_value(row, 'nReset') == 0 or
                input_value(row, 'rst') == 1 or
                value(row, 'al') == 1)

    windows = after(trace, completes, until=starts_next_command,
                    aborts=aborted)
    verdicts = []

    for window in windows:
        response = eventually(
            window,
            lambda row: value(row, 'cmd_ack') == 1,
            strong=True,
            after_activation=False,
        )
        if response[0] is not True:
            verdicts.append(response)
            continue

        ack_row = next(
            row for row in window.rows
            if value(row, 'cmd_ack') == 1
        )
        ack_pos = next(
            pos for pos, row in enumerate(trace)
            if row.get('index') == ack_row.get('index')
        )

        if ack_pos > 0 and value(trace[ack_pos - 1], 'cmd_ack') == 1:
            verdicts.append((False, ack_row.get('edge'),
                             'cmd_ack was already high before command completion'))
            continue

        high_edges = 0
        pos = ack_pos
        while pos < len(trace) and value(trace[pos], 'cmd_ack') == 1:
            high_edges += trace[pos].get('held', 0)
            pos += 1

        if pos == len(trace):
            verdicts.append((None, ack_row.get('edge'),
                             'cmd_ack remained high when the trace ended; pulse duration is incomplete'))
        elif high_edges != 1:
            verdicts.append((False, ack_row.get('edge'),
                             f'cmd_ack was high for {high_edges} clock edges, expected exactly one'))
        else:
            verdicts.append((True, ack_row.get('edge'),
                             'cmd_ack was asserted for exactly one clock edge after command completion'))

    return worst(verdicts)

def decide(trace):
    from specflow.refmodel.temporal import edges, runs

