                row.get('inputs', {}).get('ena') == 1 and
                row.get('inputs', {}).get('nReset') != 0 and
                row.get('inputs', {}).get('rst') != 1 and
                value(row, 'al') != 1):
            completions.append(row)

    if not completions:
        return (None, None,
                'no non-aborted command completion occurred in this trace')

    ack_rises = edges(trace, 'cmd_ack', 'rise')
    one_edge_runs = runs(trace, 'cmd_ack', value=1,
                        at_least=1, at_most=1)
    uncertain = None

    for row in completions:
        edge = row.get('edge')
        if value(row, 'cmd_ack') != 1:
            return (False, edge,
                    'cmd_ack was not asserted when the command finished')
        if edge not in ack_rises:
            return (False, edge,
                    'cmd_ack did not begin at command completion')
        if edge not in one_edge_runs:
            if row.get('held', 0) > 1:
                return (False, edge,
                        'cmd_ack was held longer than one clock cycle')
            uncertain = (None, edge,
                         'the trace ended before the one-clock cmd_ack pulse was fully bounded')

