def decide(trace):
    supported = {1, 2, 8, 4}
    activations = []

    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def inp(row, name, default=0):
        return row.get('inputs', {}).get(name, default)

    for i, row in enumerate(trace):
        if i == 0:
            was_active = False
        else:
            was_active = bool(out(trace[i - 1], 'fsm_active'))
        active = bool(out(row, 'fsm_active'))
        if (not was_active and active and inp(row, 'ena') == 1
                and inp(row, 'cmd') in supported):
            activations.append(i)

    if not activations:
        return (None, None, 'no supported command became active in this trace')

    for start in activations:
        finish = None
        aborted = False
        premature_ack = None

        for j in range(start, len(trace)):
            row = trace[j]
            if inp(row, 'nReset') == 0 or inp(row, 'rst') == 1:
                aborted = True
                break
            if out(row, 'al') == 1:
                aborted = True
                break

            if out(row, 'cmd_ack') == 1 and not bool(out(row, 'fsm_active')):
                finish = j
                break
            if out(row, 'cmd_ack') == 1 and premature_ack is None:
                premature_ack = j

        if aborted:
            continue

        if finish is None:
            if premature_ack is not None:
                return (False, trace[premature_ack]['edge'],
                        'cmd_ack asserted before the active command finished')
            return (None, None,
                    'the supported command did not finish before the trace ended')

        if premature_ack is not None:
            return (False, trace[premature_ack]['edge'],
                    'cmd_ack asserted before the active command finished')

        high_edges = 0
        k = finish
        while k < len(trace) and out(trace[k], 'cmd_ack') == 1:
            high_edges += trace[k].get('held', 1)
            k += 1

        if high_edges != 1:
            return (False, trace[finish]['edge'],
                    f'cmd_ack was high for {high_edges} clk edges at completion; expected exactly one')

        if k == len(trace):
            return (None, None,
                    'the completion pulse reached the end of the trace without observing its release')

    return (True, None, f'{len(activations)} supported command completion pulse(s) were one clk cycle')

