def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, worst

    def holds(cond):
        def predicate(row):
            values = {}
            values.update(row.get('inputs', {}))
            values.update(row.get('outputs', {}))
            return all(values.get(port) == value for port, value in cond.items())
        return predicate

    start = lambda row: (
        holds({'scl_i': 1, 'sda_i': 0})(row)
        and holds({'sta_condition': 1})(row)
    )
    stop = holds({'sto_condition': 1})
    reset = lambda row: (
        holds({'nReset': 0})(row) or holds({'rst': 1})(row)
    )

    windows = after(trace, start, until=stop, aborts=reset)
    verdicts = []

    for window in windows:
        verdicts.append(
            eventually(
                window,
                lambda row: row['outputs'].get('busy') == 1,
                after_activation=True,
                strong=True,
            )
        )

        if window.closed:
            closing = window.rows[-1]
            if closing['outputs'].get('busy') != 0:
                verdicts.append(
                    (False, closing['edge'],
                     'busy was not cleared low after the detected STOP condition')
                )
            else:
                verdicts.append(
                    (True, closing['edge'],
                     'busy was low at the STOP condition that closed the START window')
                )

    return worst(verdicts)

