    def reset(row):
        return row['inputs'].get('nReset') == 0 or row['inputs'].get('rst') == 1

    # Use the declared situation probes rather than inventing a numeric cmd
    # encoding.  The route applies during the active WRITE high phase.
    applies = lambda row: (
        row['inputs'].get('ena') == 1
        and probe(row, 'slave_wait')
        and probe(row, 'write_high_phase')
    )
