            verdicts.append(held)
            continue
        if held[0] is None:
            verdicts.append((None, w.edge, 'slave_wait did not complete before the trace ended'))
            continue

        # Once slave_wait clears, timing must resume and the next WRITE phase
        # must eventually pull SCL low.  No edge count is imposed.
        start = None
        for i, row in enumerate(trace):
            if i >= w.edge and not probe(row, 'slave_wait'):
                start = i
                break

        if start is None:
            verdicts.append((None, w.edge, 'SCL release was not observed'))
            continue

        resumed = None
        for i in range(start + 1, len(trace)):
            prev = trace[i - 1]
            row = trace[i]
            if not probe(row, 'write_sequence'):
                break
            if out(prev, 'scl_oen') == 1 and out(row, 'scl_oen') == 0:
                resumed = (True, row['edge'], 'after slave_wait released, scl_oen transitioned low as timing resumed')
                break

        if resumed is None:
            verdicts.append((False, trace[start]['edge'], 'after slave_wait released, scl_oen did not transition low in the next WRITE phase'))
        else:
            verdicts.append(resumed)

    return worst(verdicts)

