def decide(trace):
    activations = []
    previous = False
    for row in trace:
        out = row['outputs']
        active = (out.get('scl_sync') == 1 and
                  out.get('fsm_active') == 1 and
                  out.get('scl_oen') == 1 and
                  row['inputs'].get('ena') == 1)
        if active and not previous:
            activations.append(row)
        previous = active

    if not activations:
        return (None, None, 'no enabled active-command synchronized SCL falling event occurred')

    for start in activations:
        start_index = start['index']
        if start['outputs'].get('cmd_ack') == 1:
            return (False, start['edge'],
                    'cmd_ack occurred at the synchronized SCL falling event; low-period timing was not postponed')

        later_ack = [r for r in trace
                     if r['index'] > start_index and r['outputs'].get('cmd_ack') == 1]
        if not later_ack:
            return (None, None,
                    'synchronized SCL falling event occurred, but no later command completion was observed')

    return (True, activations[0]['edge'],
            'cmd_ack was postponed until after the synchronized SCL falling event')

