        return lambda row: all(
            row['outputs'].get(name, row['inputs'].get(name)) == value
            for name, value in cond.items()
        )

    aborted = lambda row: row['inputs'].get('nReset') == 0 or row['inputs'].get('rst') == 1
    sda_falls = edges(trace, 'sda_i', 'fall')

    # The routed observation applies only to a low-busy, enabled, START-shaped
    # raw transition while SCL is high.
    applies = lambda row: (
        row['edge'] in sda_falls
        and row['inputs'].get('ena') == 1
        and row['inputs'].get('scl_i') == 1
        and row['outputs'].get('busy') == 0
    )

    windows = after(
        trace,
        applies,
