                strong=True,
                after_activation=False,
            )
        )

    return worst(verdicts)

from specflow.refmodel.temporal import after, edges, never, worst


def decide(trace):
    def reset_active(row):
        return (row['inputs'].get('nReset') == 0 or
                row['inputs'].get('rst') == 1)

    def start_shaped_fall(row):
        return (
            row['edge'] in sda_falls
            and row['inputs'].get('busy', 0) != 1
            and row['outputs'].get('busy') == 0
            and row['inputs'].get('ena') == 1
            and row['inputs'].get('scl_i') == 1
            and row['inputs'].get('sda_i') == 0
        )

    def withdrawn(row):
        return (
            reset_active(row)
            or row['inputs'].get('ena') != 1
            or row['inputs'].get('scl_i') != 1
            or row['inputs'].get('sda_i') != 0
        )

    sda_falls = edges(trace, 'sda_i', 'fall')
    windows = after(
        trace,
        start_shaped_fall,
        until=lambda row: row['outputs'].get('sta_condition') == 1,
        aborts=withdrawn,
    )

    verdicts = []
    for window in windows:
        opening = next(
            (i for i, row in enumerate(trace)
             if row.get('edge') == window.edge and start_shaped_fall(row)),
            None,
        )
        if opening is None:
            verdicts.append((None, window.edge, 'START-shaped raw transition could not be located'))
            continue

        sta_index = next(
            (i for i in range(opening + 1, len(trace))
             if trace[i]['outputs'].get('sta_condition') == 1),
            None,
        )
        if sta_index is None:
            verdicts.append((None, window.edge,
                             'synchronized and filtered START condition was not observed'))
            continue

        early = never(window, lambda row: row['outputs'].get('busy') == 1)
        if early[0] is False:
            verdicts.append(early)
            continue
        if early[0] is None:
            verdicts.append((None, window.edge,
                             'the synchronization window was incomplete'))
            continue

        busy_index = next(
            (i for i in range(sta_index, len(trace))
             if trace[i]['outputs'].get('busy') == 1),
            None,
        )
        if busy_index is None:
            verdicts.append((None, trace[sta_index]['edge'],
                             'busy did not provide the routed post-synchronization observation'))
        else:
            verdicts.append((True, trace[busy_index]['edge'],
                             'busy remained low until the synchronized and filtered START condition'))

    return worst(verdicts)

