def decide(trace):
    relevant = []
    for i, row in enumerate(trace):
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        if inputs.get('ena') != 1 or outputs.get('filter_sample_update') != 1:
            continue

        busy = outputs.get('busy')
        previous_busy = (trace[i - 1].get('outputs', {}).get('busy')
                         if i > 0 else None)

        if outputs.get('sta_condition') == 1:
            relevant.append((row, busy == 1 and previous_busy == 0,
                             'START: busy should rise'))
        elif outputs.get('sto_condition') == 1:
            relevant.append((row, busy == 0 and previous_busy == 1,
                             'STOP: busy should clear'))

    if not relevant:
        return (None, None,
                'no enabled filter-sample update produced a majority-filtered START or STOP transition')

    for row, ok, description in relevant:
        if not ok:
            return (False, row.get('edge'),
                    f'{description} at the filtered transition; obligation requires majority-filtered sSCL/sSDA')

    return (True, relevant[-1][0].get('edge'),
            'busy showed the required transition for every enabled majority-filtered START/STOP transition')

def decide(trace):
    from specflow.refmodel.temporal import WHILE_ACTIVE, after, edges

    def applies(row):
        return (
            row['inputs'].get('ena') == 1 and
            row['outputs'].get('filter_sample_update') == 1
        )

    windows = after(trace, applies, until=WHILE_ACTIVE)
    if not windows:
        return (None, None, 'filter_sample_update never occurred while ena was high')

    busy_rises = edges(trace, 'busy', 'rise')
    busy_falls = edges(trace, 'busy', 'fall')
    first_edge = None

    for window in windows:
        if not window.rows:
            continue
        row = window.rows[0]
        edge = row['edge']
        if first_edge is None:
            first_edge = edge

        start = row['outputs'].get('sta_condition') == 1
        stop = row['outputs'].get('sto_condition') == 1

        if start and not stop:
            if edge not in busy_rises:
                return (False, edge, 'busy did not rise for the majority-filtered START transition')
        elif stop and not start:
            if edge not in busy_falls:
                return (False, edge, 'busy did not clear for the majority-filtered STOP transition')
        else:
            if edge in busy_rises or edge in busy_falls:
                return (False, edge, 'busy changed without a majority-filtered SDA transition while majority-filtered SCL was high')

    if first_edge is None:
        return (None, None, 'filter-sample activation windows contained no sampled state')
    return (True, first_edge, 'busy matched the routed START/STOP signatures of the majority-filtered histories')

