    mismatches = []
    exercised = False

    for row in trace:
        outputs = row["outputs"]
        expected = (
            outputs["fsda"] == 1
            and outputs["dsda"] == 0
            and outputs["fscl"] == 1
        )
        actual = outputs["sto_condition"] == 1

        if expected or actual:
            exercised = True
        if actual != expected:
            mismatches.append(row)

    if not exercised:
        return (None, None, "STOP condition never occurred in this trace")
    if mismatches:
        row = mismatches[0]
        return (
            False,
            row["edge"],
            "sto_condition does not equal `sSDA & ~dSDA & sSCL` for the filtered STOP condition"
        )
    return (True, None, "sto_condition exactly matches `sSDA & ~dSDA & sSCL`")

