def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, throughout, worst

    def holds(conditions):
        def predicate(row):
            for port, value in conditions.items():
                if port in row.get('outputs', {}):
                    actual = row['outputs'][port]
                else:
                    actual = row.get('inputs', {}).get(port)
                if actual != value:
                    return False
            return True
        return predicate

    def any_of(alternatives):
        predicates = [holds(condition) for condition in alternatives]
        return lambda row: any(predicate(row) for predicate in predicates)

    # Transcribed from the normalized activation for REQ-0069.
    activation_inputs = {'scl_i': 1, 'sda_i': 0}
    activation_opens_on = [{'sta_condition': 1}]
    activation_until = [{'sto_condition': 1}]
    activation_aborts_on = [{'nReset': 0}, {'rst': 1}]
    effect_follows = True

    applies = holds(activation_inputs)
    opens = any_of(activation_opens_on)
    starts = lambda row: applies(row) and opens(row)
    closes = any_of(activation_until)
    aborts = any_of(activation_aborts_on)

    windows = after(trace, starts, until=closes, aborts=aborts)
    verdicts = []

    for window in windows:
        verdicts.append(
            eventually(
                window,
                lambda row: row['outputs'].get('busy') == 1,
                strong=True,
                after_activation=effect_follows
            )
        )
        verdicts.append(
            throughout(
                window,
                lambda row: row['outputs'].get('busy') == 1,
                after_activation=effect_follows
            )
        )

        if window.closed:
            stop_rows = [
                row for row in window.rows
                if row['outputs'].get('sto_condition') == 1
            ]
            if stop_rows:
                stop_row = stop_rows[-1]
                if stop_row['outputs'].get('busy') != 0:
                    verdicts.append((
                        False,
                        stop_row['edge'],
                        'busy remained high at the detected STOP condition; it must be cleared low'
                    ))
                else:
                    verdicts.append((
                        True,
                        stop_row['edge'],
                        'busy was cleared low at the detected STOP condition'
                    ))

    return worst(verdicts)

