    def out(row, name):
        return row['outputs'].get(name)

    def any_condition(alts):
        def predicate(row):
            return any(all(out(row, port) == value for port, value in alt.items())
                       for alt in alts)
        return predicate

    al_rises = edges(trace, 'al', 'rise')
    prior = {}
    for i in range(1, len(trace)):
        prior[trace[i]['edge']] = trace[i - 1]

    def arbitration_loss(row):
        if row['edge'] not in al_rises or row['inputs'].get('ena') != 1:
            return False
        before = prior.get(row['edge'])
        if before is None:
            return False
        return (out(before, 'fsm_active') == 1 and
                out(before, 'stop_sequence') != 1)

    def released(row):
        return (out(row, 'scl_oen') == 1 and
                out(row, 'sda_oen') == 1)

    def required_state(row):
        return (out(row, 'fsm_active') == 0 and released(row))

    aborts = any_condition([
        {'nReset': 0},
        {'rst': 1},
    ])

    windows = after(trace, arbitration_loss, until=released, aborts=aborts)
    follows = True
    return worst([
