def decide(trace):
    matches = []
    for row in trace:
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})

        # Reset aborts the sampling situation.
        if inputs.get('nReset') == 0 or inputs.get('rst') == 1:
            continue

        # Normalized activation: timing/filtering enabled, SCL externally high,
        # and the declared filtered-SCL rising-edge situation is present.
        if (inputs.get('ena') == 1
                and inputs.get('scl_i') == 1
                and outputs.get('filtered_scl_rise') == 1):
            matches.append(row)
            expected = outputs.get('fsda')
            actual = outputs.get('dout')
            if actual != expected:
                return (False, row.get('edge'),
                        f"dout was {actual}, expected the filtered SDA value fsda={expected} "
                        "at the rising edge of the filtered SCL signal")

    if not matches:
        return (None, None,
                'filtered SCL never had a qualified rising edge; data sampling did not occur')

    return (True, matches[-1].get('edge'),
            f"dout captured fsda at {len(matches)} qualified filtered SCL rising edge(s)")

