    seen = False
    for row in trace:
        inputs = row['inputs']
        outputs = row['outputs']

        # The normalized activation: filtered SCL rising edge while enabled
        # and the external SCL input is high. Reset aborts this situation.
        if inputs.get('nReset') == 0 or inputs.get('rst') == 1:
            continue
        if inputs.get('ena') != 1 or inputs.get('scl_i') != 1:
            continue
        if outputs.get('filtered_scl_rise') != 1:
            continue

        seen = True
        expected = outputs.get('fsda')
