                if port not in values:
                    values = row.get('inputs', {})
                if values.get(port) != value:
                    return False
            return True
        return predicate

    def any_condition(alternatives):
        predicates = [holds(condition) for condition in alternatives]
        return lambda row: any(predicate(row) for predicate in predicates)

    # The declared probe identifies the STOP sequence without assuming an
    # unstated numeric encoding for the symbolic STOP command.
    windows = after(
        trace,
        holds({'stop_sequence': 1}),
        until=holds({'cmd_ack': 1}),
        aborts=any_condition([{'nReset': 0}, {'rst': 1}])
    )

    follows = True
    ordered = [
        sequence(
            window,
            holds({'sda_oen': 0}),
            holds({'scl_oen': 1}),
            holds({'scl_oen': 1, 'sda_oen': 1}),
            strong=True,
            after_activation=follows
        )
        for window in windows
    ]

    # Once SDA is released during the STOP sequence, SCL must also be
    # released; this prevents releasing SDA while SCL is driven low.
