    def output_holds(values):
        return lambda row: all(
            row['outputs'].get(port) == value
            for port, value in values.items()
        )

    def any_output_holds(alternatives):
        predicates = [output_holds(alt) for alt in alternatives]
        return lambda row: any(predicate(row) for predicate in predicates)

    # The specification supplies no authoritative numeric encoding table for
    # cmd.  stop_sequence is the declared live signature of the STOP state.
    opens = lambda row: (
        row['inputs'].get('ena') == 1 and
        row['outputs'].get('stop_sequence') == 1
    )
