    aborts = any_output_holds([
        {'nReset': 0},
        {'rst': 1}
    ])

    windows = after(trace, opens, until=closes, aborts=aborts)
    follows = True

    drives_sda_low = output_holds({'sda_oen': 0})
    releases_scl = output_holds({'scl_oen': 1})
    releases_sda_while_scl_released = output_holds({
        'scl_oen': 1,
        'sda_oen': 1
    })

    return worst([
        sequence(
            window,
            drives_sda_low,
            releases_scl,
            releases_sda_while_scl_released,
            strong=True,
            after_activation=follows
        )
        for window in windows
    ])

