def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, throughout, worst

    def holds(cond):
        def predicate(row):
            for port, value in cond.items():
                values = row.get("outputs", {})
                if port not in values:
                    values = row.get("inputs", {})
                if values.get(port) != value:
                    return False
            return True
        return predicate

    def any_condition(alternatives):
        predicates = [holds(condition) for condition in alternatives]
        return lambda row: any(predicate(row) for predicate in predicates)

    # The declared read_window probe is the situation named by this clause.
    windows = after(
        trace,
        holds({"read_window": 1}),
        until=holds({"scl_oen": 0}),
        aborts=any_condition([
            {"al": 1},
            {"nReset": 0},
            {"rst": 1},
        ]),
    )

    fell = edges(trace, "scl_oen", "fall")
    verdicts = []
    for window in windows:
        verdicts.append(
            throughout(
                window,
                lambda row: row["outputs"].get("scl_oen") == 1,
                after_activation=True,
            )
        )
        verdicts.append(
            eventually(
                window,
                lambda row: row["edge"] in fell,
                strong=True,
                after_activation=True,
            )
        )

    return worst(verdicts)

def decide(trace):
    def is_active(row):
        return (row.get('inputs', {}).get('ena') == 1 and
                row.get('outputs', {}).get('read_window') == 1)

    def aborted(row):
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        return (outputs.get('al') == 1 or
                inputs.get('nReset') == 0 or
                inputs.get('rst') == 1)

    verdicts = []
    activations = []
    previous_active = False

    for i, row in enumerate(trace):
        active = is_active(row)
        if active and not previous_active:
            activations.append(i)
        previous_active = active

    if not activations:
        return (None, None, 'READ sample window never occurred')

    for start in activations:
        released_seen = False
        closed = False
        failure_edge = None

        for j in range(start + 1, len(trace)):
            row = trace[j]
            outputs = row.get('outputs', {})

            if aborted(row):
                verdicts.append((None, row.get('edge'),
                                 'READ sample-window obligation aborted by reset or arbitration loss'))
                closed = True
                break

            scl_oen = outputs.get('scl_oen')
            if scl_oen == 1:
                released_seen = True
                continue

            if scl_oen == 0:
                if not released_seen:
                    failure_edge = row.get('edge')
                    verdicts.append((False, failure_edge,
                                     'SCL was driven low before any later sample-window state released it high'))
                else:
                    verdicts.append((True, row.get('edge'),
                                     'SCL remained released high during the sample window and then became driven low'))
                closed = True
                break

            failure_edge = row.get('edge')
            verdicts.append((False, failure_edge,
                             'scl_oen had a value other than released high or driven low'))
            closed = True
            break

        if not closed:
            if released_seen:
                verdicts.append((False, trace[-1].get('edge'),
                                 'SCL remained released high, but the required subsequent drive-low state was absent'))
            else:
                verdicts.append((None, trace[-1].get('edge'),
                                 'the READ sample-window evidence was incomplete'))

    failures = [v for v in verdicts if v[0] is False]
    if failures:
        return failures[0]
    if any(v[0] is True for v in verdicts):
        return (True, next(v[1] for v in reversed(verdicts) if v[0] is True),
                'all observed READ sample windows released SCL high and then drove it low')
    return (None, None, 'READ sample-window attempts were aborted or incomplete')

