def decide(trace):
    def value(row, port):
        return row['outputs'].get(port, row['inputs'].get(port))

    def rises(port):
        return edges(trace, port, 'rise')

    def is_abort(row):
        return (
            value(row, 'al') == 1 or
            value(row, 'nReset') == 0 or
            value(row, 'rst') == 1
        )

    starts = rises('write_sequence')
    windows = after(
        trace,
        lambda row: (
            row['edge'] in starts and
            value(row, 'cmd') == 4 and
            value(row, 'ena') == 1
        ),
        until=lambda row: value(row, 'write_sequence') == 0,
        aborts=is_abort,
    )

    verdicts = []
    for window in windows:
        rows = window.rows[1:]
        din_value = window.value('din')

        sda_index = None
        for i, row in enumerate(rows):
            if value(row, 'sda_oen') == din_value:
                sda_index = i
                break

        if sda_index is None:
            if window.closed:
                verdicts.append((False, rows[-1]['edge'] if rows else window.edge,
                                 'SDA was never set according to din during the WRITE sequence'))
            else:
                verdicts.append((None, None,
                                 'WRITE sequence window ended before the din-selected SDA state was observed'))
            continue

        high_index = None
        for i in range(sda_index, len(rows)):
            if value(rows[i], 'scl_oen') == 1:
                high_index = i
                break

        if high_index is None:
            if window.closed:
                verdicts.append((False, rows[-1]['edge'] if rows else window.edge,
                                 'SCL was not released high after SDA was set according to din'))
            else:
                verdicts.append((None, None,
                                 'WRITE sequence window ended before SCL release was observed'))
            continue

        if value(rows[high_index], 'sda_oen') != din_value:
            verdicts.append((False, rows[high_index]['edge'],
                             'SDA output-enable did not match din during the WRITE high phase'))
            continue

        low_index = None
        for i in range(high_index + 1, len(rows)):
            if value(rows[i], 'scl_oen') == 0:
                low_index = i
                break

        if low_index is not None:
            verdicts.append((True, rows[low_index]['edge'],
                             'SDA matched din, SCL was released high, then SCL was pulled low'))
        elif window.closed:
            verdicts.append((False, rows[-1]['edge'],
                             'SCL did not become 0 after the WRITE high phase'))
        else:
            verdicts.append((None, None,
                             'WRITE sequence window ended before the subsequent SCL-low state was observed'))

    return worst(verdicts)

