def decide(trace):
    saw_reset = False
    armed = False
    checks = []

    for i, row in enumerate(trace):
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        reset_active = inputs.get('nReset') == 0 or inputs.get('rst') == 1

        if reset_active:
            saw_reset = True
            armed = False
            continue

        if saw_reset and not armed:
            armed = True

        if not armed or inputs.get('ena') != 1:
            continue
        if not outputs.get('filtered_scl_rise'):
            continue
        if i == 0:
            continue

        previous = trace[i - 1].get('inputs', {})
        if previous.get('sda_i') != inputs.get('sda_i'):
            continue

        checks.append((row, outputs.get('fsda')))

    if not saw_reset:
        return (None, None, 'reset was not exercised; post-reset sampling was not activated')
    if not checks:
        return (None, None, 'no qualified filtered SCL rising edge occurred after reset')

    for row, expected in checks:
        actual = row.get('outputs', {}).get('dout')
        if actual != expected:
            return (False, row.get('edge'),
                    f'dout was {actual} at the filtered SCL sampling edge; expected the filtered SDA value {expected}')

    return (True, checks[-1][0].get('edge'),
            f'dout matched the filtered SDA value at {len(checks)} post-reset filtered SCL sampling edge(s)')

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, throughout, worst

    def reset_active(row):
        return (row['inputs'].get('nReset') == 0 or
                row['inputs'].get('rst') == 1)

    nreset_rise = edges(trace, 'nReset', 'rise')
    rst_fall = edges(trace, 'rst', 'fall')
    release_edges = nreset_rise | rst_fall

    def post_reset_release(row):
        return (row['edge'] in release_edges and
                row['inputs'].get('nReset') == 1 and
                row['inputs'].get('rst') == 0)

    windows = after(trace, post_reset_release,
                    until=TO_END,
                    aborts=reset_active)

    verdicts = []
    for window in windows:
        sampled = []
        ordinary = []
        for row in window.rows:
            if row['inputs'].get('ena') != 1:
                continue
            rise = row['outputs'].get('filtered_scl_rise') == 1
            if rise:
                sampled.append(row)
            else:
                ordinary.append(row)

        if not sampled or not ordinary:
            verdicts.append((None, window.edge,
                             'post-reset sampling was not exercised on both a filtered SCL rise and a non-rise interval'))
            continue

        def sampled_value(row):
            if row['inputs'].get('ena') != 1:
                return True
            if row['outputs'].get('filtered_scl_rise') != 1:
                return True
            return row['outputs'].get('dout') == row['outputs'].get('fsda')

        verdict = throughout(window, sampled_value, after_activation=False)
        if verdict[0] is False:
            bad = next((r for r in sampled
                        if r['outputs'].get('dout') != r['outputs'].get('fsda')),
                       sampled[0])
            verdicts.append((False, bad['edge'],
                             'after reset, on a filtered SCL rising edge with ena high, dout did not reflect the sampled filtered SDA value'))
        else:
            verdicts.append(verdict)

    return worst(verdicts)

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, edges, worst

    def reset_active(row):
        ins = row.get('inputs', {})
        return ins.get('nReset') == 0 or ins.get('rst') == 1

    saw_reset = any(reset_active(row) for row in trace)
    if not saw_reset:
        return (None, None, 'reset was not exercised; post-reset bus sampling was not activated')

    # A qualified sampling opportunity is the routed observation condition:
    # after reset, ena high, stable SDA, and a filtered SCL rising edge.
    eligible = set()
    for i, row in enumerate(trace):
        ins = row.get('inputs', {})
        out = row.get('outputs', {})
        if reset_active(row) or ins.get('ena') != 1:
            continue
        if not out.get('filtered_scl_rise'):
            continue
        if i == 0:
            continue
        prev = trace[i - 1].get('inputs', {})
        if prev.get('sda_i') != ins.get('sda_i'):
            continue
        # Require that some reset has already occurred and that this row is
        # outside the active-reset interval.
        if any(reset_active(trace[j]) for j in range(i)):
            eligible.add(row.get('index', i))

    if not eligible:
        return (None, None, 'no qualified post-reset filtered SCL sampling edge occurred')

    def applies(row):
        return row.get('index') in eligible

    def aborts(row):
        return reset_active(row)

    windows = after(trace, applies, overlap=True, until=TO_END, aborts=aborts)
    verdicts = []
    for w in windows:
        expected = w.value('sda_i')
        verdicts.append(
            eventually(
                w,
                lambda row, expected=expected: row.get('outputs', {}).get('dout') == expected,
                strong=True,
                after_activation=True))

    return worst(verdicts)

