def decide(trace):
    outcomes = []

    def inp(row, name, default=None):
        return row.get('inputs', {}).get(name, default)

    def out(row, name, default=None):
        return row.get('outputs', {}).get(name, default)

    def rising(rows, pos, name):
        if pos == 0:
            return False
        return out(rows[pos - 1], name) == 0 and out(rows[pos], name) == 1

    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]

        # Raw START-shaped transition: enabled, out of reset, SCL high,
        # and SDA changes high to low.  The transition, rather than the
        # resting low level, identifies the sampling event.
        if not (
            inp(row, 'ena') == 1 and
            inp(row, 'nReset') == 1 and
            inp(row, 'rst') == 0 and
            inp(prev, 'scl_i') == 1 and
            inp(row, 'scl_i') == 1 and
            inp(prev, 'sda_i') == 1 and
            inp(row, 'sda_i') == 0
        ):
            continue

        baseline_busy = out(prev, 'busy')
        decided = None

        for j in range(i, len(trace)):
            cur = trace[j]

            if inp(cur, 'nReset') != 1 or inp(cur, 'rst') == 1 or inp(cur, 'ena') != 1:
                decided = None
                break

            if rising(trace, j, 'busy'):
                decided = (True, cur.get('edge'),
                           'busy rose after the raw SDA transition, consistent with captured and filtered START processing')
                break

            # A stable START-shaped transition must keep raw SCL high.
            # If it does not, this occurrence is outside the routed case.
            if inp(cur, 'scl_i') != 1:
                decided = None
                break

            # If SDA returns high before busy rises, this was not a
            # sufficiently persistent transition.  The routed otherwise
            # behaviour is that busy remains unchanged.
            if j > i and inp(cur, 'sda_i') == 1:
                unchanged = all(out(trace[k], 'busy') == baseline_busy
                                for k in range(i, j + 1))
                decided = (unchanged, cur.get('edge'),
                           'busy remained unchanged for a raw SDA transition that did not persist into a captured START'
                           if unchanged else
                           'busy changed even though the raw SDA transition did not persist into a captured START')
                break

        if decided is None:
            outcomes.append((None, row.get('edge'),
                             'raw START-shaped transition remained incomplete in the trace'))
        else:
            outcomes.append(decided)

    if not outcomes:
        return (None, None, 'no enabled, out-of-reset raw SDA high-to-low transition while SCL was high')
    for result in outcomes:
        if result[0] is False:
            return result
    for result in outcomes:
        if result[0] is None:
            return result
    return (True, outcomes[-1][1], 'all observed routed raw transitions produced the specified busy distinction')

def decide(trace):
    if not trace:
        return (None, None, 'no clocked sampling events occurred')

    def value(row, port):
        return row['outputs'].get(port, row['inputs'].get(port))

    busy_rises = set()
    sda_falls = set()
    for i in range(1, len(trace)):
        prev = value(trace[i - 1], 'sda_i')
        cur = value(trace[i], 'sda_i')
        if prev == 1 and cur == 0:
            sda_falls.add(trace[i]['edge'])
        old_busy = value(trace[i - 1], 'busy')
        new_busy = value(trace[i], 'busy')
        if old_busy == 0 and new_busy == 1:
            busy_rises.add(trace[i]['edge'])

    activations = []
    for i, row in enumerate(trace):
        if trace[i]['edge'] not in sda_falls:
            continue
        if value(row, 'scl_i') == 1 and value(row, 'ena') == 1:
            activations.append(i)

    if not activations:
        return (None, None, 'no qualifying raw SDA falling transition occurred')

    for start in activations:
        initial_busy = value(trace[start], 'busy')
        ended = False
        for j in range(start, len(trace)):
            row = trace[j]
            edge = row['edge']
            busy = value(row, 'busy')
            if j > start and edge in busy_rises:
                if initial_busy == 0:
                    return (True, edge, 'busy rose after the captured and filtered START-shaped raw transition')
                ended = True
                break
            if j > start and (value(row, 'scl_i') != 1 or
                              value(row, 'sda_i') != 0 or
                              value(row, 'ena') != 1):
                if busy != initial_busy:
                    return (False, edge, 'busy changed although the raw transition ended before a captured START effect')
                ended = True
                break
        if not ended:
            return (None, None, 'the qualifying raw transition persisted to the end without observable completion')

    return (True, None, 'raw transitions that ended before capture left busy unchanged')

