def decide(trace):
    candidates = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        prev_sda = prev['inputs'].get('sda_i')
        sda = row['inputs'].get('sda_i')
        scl = row['inputs'].get('scl_i')
        busy = row['outputs'].get('busy')
        if prev_sda == 1 and sda == 0 and scl == 1 and busy == 0:
            candidates.append(i)

    if not candidates:
        return (None, None, 'no qualifying raw SDA high-to-low transition while SCL was high')

    saw_late_busy = False
    for start in candidates:
        initial_busy = trace[start]['outputs'].get('busy')
        j = start
        while j < len(trace):
            row = trace[j]
            current_busy = row['outputs'].get('busy')
            if j > start and current_busy != initial_busy:
                if row['outputs'].get('sta_condition') != 1:
                    return (False, row['edge'], 'busy changed before the synchronized and filtered START condition was detected')
                saw_late_busy = True
                break
            if row['outputs'].get('sta_condition') == 1:
                k = j
                while k < len(trace):
                    if trace[k]['outputs'].get('busy') != initial_busy:
                        saw_late_busy = True
                        break
                    k += 1
                break
            j += 1

    if saw_late_busy:
        return (True, None, 'busy changed only after the synchronized and filtered START condition was detected')
    return (None, None, 'the trace ended without observing both a synchronized START and its busy change')

def decide(trace):
    from specflow.refmodel.temporal import edges

    sda_falls = edges(trace, "sda_i", "fall")
    sta_rises = edges(trace, "sta_condition", "rise")
    busy_rises = edges(trace, "busy", "rise")

    row_by_edge = {row["edge"]: (i, row) for i, row in enumerate(trace)}
    saw_activation = False
    saw_valid_observation = False
    passed_edges = []

    for i, row in enumerate(trace):
        if row["edge"] not in sda_falls:
            continue
        if row["inputs"].get("scl_i") != 1:
            continue

        saw_activation = True
        sta_after = [
            row_by_edge[e][0] for e in sta_rises
            if e in row_by_edge and row_by_edge[e][0] > i
        ]
        sta_index = min(sta_after) if sta_after else None

        busy_after = [
            row_by_edge[e][0] for e in busy_rises
            if e in row_by_edge and row_by_edge[e][0] >= i
        ]
        busy_index = min(busy_after) if busy_after else None

        if busy_index is not None and (sta_index is None or busy_index < sta_index):
            bad_edge = trace[busy_index]["edge"]
            return (False, bad_edge,
                    "busy rose before the synchronized and filtered START condition; "
                    "the capture stage did not precede controller use")

        if sta_index is not None and busy_index is not None and busy_index >= sta_index:
            saw_valid_observation = True
            passed_edges.append(trace[busy_index]["edge"])

    if not saw_activation:
        return (None, None, "no raw SDA high-to-low transition while SCL was high")
    if not saw_valid_observation:
        return (None, None,
                "no busy rise was observed after a synchronized and filtered START; "
                "the routed observation was not exercised")
    return (True, passed_edges[0],
            "busy rose only after the synchronized and filtered START condition, "
            "consistent with capture before controller use")

