def decide(trace):
    saw_activation = False
    saw_evidence = False
    last_active = None

    for row in trace:
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        ena = inputs.get('ena') == 1
        reset = inputs.get('nReset') == 0 or inputs.get('rst') == 1

        if not ena or reset:
            last_active = None
            continue

        saw_activation = True
        if 'clk_cnt' not in inputs or 'filter_cnt' not in outputs:
            return (None, row.get('edge'),
                    'filter_cnt or clk_cnt is unavailable in this trace')

        interval = inputs['clk_cnt'] >> 2
        count = outputs['filter_cnt']

        # A zero interval is explicitly defined as sampling on every enabled
        # clock, so the counter must remain at zero in the active window.
        if interval == 0:
            if count != 0:
                return (False, row.get('edge'),
                        'A filter counter, `filter_cnt`, derives its sampling '
                        'interval from `clk_cnt >> 2`; derived interval is 0 '
                        'but filter_cnt is not 0')
            saw_evidence = True
        else:
            # A counter reload is observable without assuming its latency as
            # an increase in the state-compressed counter value.  The initial
            # active state may itself be the reloaded value.
            reloaded = (last_active is None or
                        count > last_active[1])
            if reloaded:
                if count != interval:
                    return (False, row.get('edge'),
                            'A filter counter, `filter_cnt`, derives its '
                            'sampling interval from `clk_cnt >> 2`; observed '
                            f'reload value {count}, expected {interval}')
                saw_evidence = True
            elif count == interval:
                saw_evidence = True

        last_active = (inputs['clk_cnt'], count)

    if not saw_activation:
        return (None, None, 'filter timing progression was never enabled')
    if not saw_evidence:
        return (None, None,
                'filter timing was enabled, but no filter-counter interval '
                'reload was observable')
    return (True, None,
            'observed filter_cnt consistent with the stated `clk_cnt >> 2` '
            'sampling interval')

def decide(trace):
    def reset(row):
        inp = row.get('inputs', {})
        return inp.get('nReset') == 0 or inp.get('rst') == 1

    def enabled(row):
        return row.get('inputs', {}).get('ena') == 1 and not reset(row)

    def value(row):
        return row.get('outputs', {}).get('filter_cnt')

    def expired(row):
        return row.get('outputs', {}).get('filter_cnt_expired') == 1

    failures = []
    witnessed = False
    previous_expired = False

    for i, row in enumerate(trace):
        if not enabled(row):
            previous_expired = False
            continue

        now_expired = expired(row)
        opening = now_expired and not previous_expired
        previous_expired = now_expired

        if not opening:
            continue

        witnessed = True
        clk_cnt = row.get('inputs', {}).get('clk_cnt')
        if not isinstance(clk_cnt, int):
            return (None, row.get('edge'),
                    'clk_cnt was unavailable at a filter-counter expiration')

        interval = clk_cnt >> 2
        allowed = {interval}
        if interval > 0:
            allowed.add(interval - 1)

        # A zero interval means the filter counter remains at zero; this is
        # the specified zero-interval behavior rather than a reload edge.
        if interval == 0:
            j = i
            while j < len(trace) and enabled(trace[j]):
                counter = value(trace[j])
                if counter != 0:
                    failures.append((trace[j].get('edge'), counter, interval))
                    break
                j += 1
            continue

        # Locate the first visible nonzero counter value after expiration.
        # Do not impose a cycle count; distinct-state latency is unspecified.
        j = i
        found = False
        while j < len(trace) and enabled(trace[j]):
            counter = value(trace[j])
            if isinstance(counter, int) and counter != 0:
                found = True
                if counter not in allowed:
                    failures.append((trace[j].get('edge'), counter, interval))
                break
            j += 1

        if not found:
            # The trace ended or the attempt was otherwise not observable far
            # enough to distinguish a missing reload from an incomplete trace.
            continue

    if failures:
        edge, actual, interval = failures[0]
        return (False, edge,
                f"filter_cnt reloaded to {actual}; expected sampling interval derived from the phrase 'right-shifting clk_cnt by two bits' as {interval} (or counter representation {interval - 1})")

    if not witnessed:
        return (None, None,
                'filter-counter expiration never occurred while ena was high and reset was inactive')

    return (True, None,
            "filter_cnt used a value consistent with the sampling interval derived by right-shifting clk_cnt by two bits")

def decide(trace):
    def reset(row):
        inp = row.get('inputs', {})
        return inp.get('nReset') == 0 or inp.get('rst') == 1

    def active(row):
        return row.get('inputs', {}).get('ena') == 1 and not reset(row)

    def updated(row):
        return row.get('outputs', {}).get('filter_sample_update') == 1

    updates = []
    for i, row in enumerate(trace):
        if active(row) and updated(row):
            updates.append(i)

    if len(updates) < 2:
        return (None, None,
                "fewer than two enabled filter-sample updates were observed; the interval derived from clk_cnt >> 2 cannot be distinguished")

    for a, b in zip(updates, updates[1:]):
        # State rows are compressed, so count the clock edges represented by
        # the states between the two sample updates.
        elapsed = sum(trace[k].get('held', 1) for k in range(a, b))
        cnt = trace[a].get('inputs', {}).get('clk_cnt')
        if not isinstance(cnt, int):
            return (None, trace[a].get('edge'),
                    "clk_cnt was unavailable while checking the filter sampling interval")

        interval = cnt >> 2
        if interval == 0:
            if elapsed != 1:
                return (False, trace[b].get('edge'),
                        f"filter samples were {elapsed} enabled edges apart; the interval derived from 'right-shifting clk_cnt by two bits' is 0, which means every enabled clock")
        else:
            allowed = {interval}
            if interval > 1:
                allowed.add(interval - 1)
            allowed.add(interval + 1)
            if elapsed not in allowed:
                return (False, trace[b].get('edge'),
                        f"filter samples were {elapsed} enabled edges apart; clk_cnt >> 2 is {interval}, allowing equivalent counter conventions {sorted(allowed)}")

    return (True, trace[updates[1]].get('edge'),
            "filter-sample spacing is consistent with the interval derived by the stated operation 'right-shifting clk_cnt by two bits'")

