            continue
        if inputs.get('ena') != 1:
            continue
        if outputs.get('filter_sample_update') != 1:
            continue

        checked = True
        last_edge = row.get('edge')
        busy = outputs.get('busy')
        sta = outputs.get('sta_condition') == 1
        sto = outputs.get('sto_condition') == 1

        if sta and busy != 1:
            return (False, row.get('edge'),
                    'at a filter sample update with a majority-filtered START transition, busy was not high')
        if sto and busy != 0:
            return (False, row.get('edge'),
                    'at a filter sample update with a majority-filtered STOP transition, busy was not low')

        if not sta and not sto and i > 0:
            previous = trace[i - 1]
            previous_outputs = previous.get('outputs', {})
            if previous_outputs.get('busy') == busy:
                continue
            return (False, row.get('edge'),
                    'busy changed at a filter sample update with no majority-filtered SDA transition')

    if not checked:
        return (None, None, 'no enabled filter-sample update occurred outside reset')
    return (True, last_edge, 'busy matched the majority-filtered START/STOP transition signatures and stayed unchanged otherwise')

def decide(trace):
    saw_activation = False

    for i, row in enumerate(trace):
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})

        # Reset aborts the filtering observation window.
        if inputs.get('nReset') == 0 or inputs.get('rst') == 1:
            continue
        if inputs.get('ena') != 1:
            continue
        if outputs.get('filter_sample_update') != 1:
            continue

        saw_activation = True
        if i == 0:
            continue

        previous = trace[i - 1]
        previous_outputs = previous.get('outputs', {})
        fsda_prev = previous_outputs.get('fsda')
        fsda_now = outputs.get('fsda')
        fscl_now = outputs.get('fscl')
        busy_prev = previous_outputs.get('busy')
        busy_now = outputs.get('busy')

        if fsda_prev is None or fsda_now is None or fscl_now is None:
            return (False, row.get('edge'),
                    'declared fscl/fsda probes or busy output are missing')

        if fsda_now != fsda_prev and fscl_now == 1:
            expected_busy = 1 if fsda_prev == 1 and fsda_now == 0 else 0
        else:
            expected_busy = busy_prev

        if busy_now != expected_busy:
            return (False, row.get('edge'),
                    'busy does not match the majority-filtered SDA transition: '
                    'fsda changes while fscl is high set or clear busy, and '
                    'otherwise busy must retain its prior value')

    if not saw_activation:
        return (None, None, 'filter sampling update never occurred')
    return (True, None,
            'busy matched the filtered fscl/fsda majority-transition behavior '
            'at every filter sample update')

