def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, edges, stable, worst

    def out(row, port):
        return row['outputs'].get(port)

    def is_start(row):
        return out(row, 'sta_condition') == 1

    def is_stop(row):
        return out(row, 'sto_condition') == 1

    def enabled(row):
        return row['inputs'].get('ena') == 1

    starts = after(
        trace,
        lambda r: enabled(r) and is_start(r),
        until=TO_END,
    )
    stops = after(
        trace,
        lambda r: enabled(r) and is_stop(r),
        until=TO_END,
    )

    busy_rises = edges(trace, 'busy', 'rise')
    busy_falls = edges(trace, 'busy', 'fall')

    positive = [
        eventually(
            w,
            lambda r: r['edge'] in busy_rises,
            strong=True,
            after_activation=False,
        )
        for w in starts
    ] + [
        eventually(
            w,
            lambda r: r['edge'] in busy_falls,
            strong=True,
            after_activation=False,
        )
        for w in stops
    ]

    raw_edges = edges(trace, 'scl_i', 'change') | edges(trace, 'sda_i', 'change')
    raw_only = after(
        trace,
        lambda r: (
            enabled(r)
            and r['edge'] in raw_edges
            and not is_start(r)
            and not is_stop(r)
        ),
        until=lambda r: is_start(r) or is_stop(r),
    )
    negative = [stable(w, 'busy') for w in raw_only]

    have_positive = bool(starts or stops)
    have_negative = bool(raw_only)
    verdicts = positive + negative

    if not have_positive and not have_negative:
        return (None, None, 'no filtered START/STOP or raw-only bus activity occurred')

    result = worst(verdicts)
    if result[0] is False:
        return result
    if not (have_positive and have_negative):
        return (None, None, 'only one of the routed filtered/raw activity cases occurred')
    return result

def decide(trace):
    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def inp(row, name, default=0):
        return row.get('inputs', {}).get(name, default)

    def rising(port, i):
        if i == 0:
            return bool(out(trace[i], port))
        return not bool(out(trace[i - 1], port)) and bool(out(trace[i], port))

    events = []
    for i, row in enumerate(trace):
        if not inp(row, 'ena', 0):
            continue
        if rising('sta_condition', i):
            events.append((i, 'START', 1))
        if rising('sto_condition', i):
            events.append((i, 'STOP', 0))

    verdicts = []
    for pos, kind, target in events:
        close = None
        opposite = 'sto_condition' if kind == 'START' else 'sta_condition'
        for j in range(pos + 1, len(trace)):
            if rising(opposite, j):
                close = j
                break
        end = close if close is not None else len(trace)
        found = None
        for j in range(pos + 1, end + 1):
            if j < len(trace) and out(trace[j], 'busy') == target:
                found = j
                break
        if found is not None:
            verdicts.append((True, trace[found]['edge'],
                             f'busy reached {target} after filtered {kind}'))
        elif close is not None:
            verdicts.append((False, trace[close]['edge'],
                             f'busy did not reach {target} after filtered {kind}'))
        else:
            verdicts.append((None, None,
                             f'the response to filtered {kind} was not observed before the trace ended'))

    raw_edges = []
    for i, row in enumerate(trace):
        if not inp(row, 'ena', 0) or i == 0:
            continue
        raw_changed = (inp(row, 'scl_i') != inp(trace[i - 1], 'scl_i') or
                       inp(row, 'sda_i') != inp(trace[i - 1], 'sda_i'))
        if raw_changed:
            raw_edges.append(i)

    for pos in raw_edges:
        if rising('sta_condition', pos) or rising('sto_condition', pos):
            continue
        close = None
        for j in range(pos + 1, len(trace)):
            if rising('sta_condition', j) or rising('sto_condition', j):
                close = j
                break
        end = close if close is not None else len(trace)
        changed = None
        for j in range(pos + 1, end + 1):
            if j < len(trace) and out(trace[j], 'busy') != out(trace[pos], 'busy'):
                changed = j
                break
        if changed is not None:
            verdicts.append((False, trace[changed]['edge'],
                             'busy changed during raw SCL/SDA activity without a filtered START/STOP condition'))
        elif close is not None:
            verdicts.append((True, trace[close]['edge'],
                             'busy remained unchanged during raw activity without a filtered START/STOP condition'))
        else:
            verdicts.append((None, None,
                             'raw activity had no filtered START/STOP condition before the trace ended'))

    if not verdicts:
        return (None, None, 'no enabled filtered condition or raw bus activity occurred')
    for verdict in verdicts:
        if verdict[0] is False:
            return verdict
    for verdict in verdicts:
        if verdict[0] is True:
            return verdict
    return verdicts[0]

