def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, sequence, worst

    def _row_value(row, port):
        return row['outputs'].get(port, row['inputs'].get(port))

    def _transition_windows(port):
        result = []
        for edge in sorted(edges(trace, port, 'change')):
            result.extend(after(
                trace,
                lambda row, edge=edge: row['edge'] == edge,
                until=TO_END
            ))
        return result

    follows = False
    verdicts = []

    for w in _transition_windows('fscl'):
        old = w.past('fscl')
        new = w.value('fscl')
        verdicts.append(sequence(
            w,
            lambda row, old=old: _row_value(row, 'dscl') == old,
            lambda row, new=new: _row_value(row, 'dscl') == new,
            strong=True,
            after_activation=follows
        ))

    for w in _transition_windows('fsda'):
        old = w.past('fsda')
        new = w.value('fsda')
        verdicts.append(sequence(
            w,
            lambda row, old=old: _row_value(row, 'dsda') == old,
            lambda row, new=new: _row_value(row, 'dsda') == new,
            strong=True,
            after_activation=follows
        ))

    return worst(verdicts)

def decide(trace):
    def transitions(port):
        events = []
        previous = None
        have_previous = False
        for i, row in enumerate(trace):
            value = row['outputs'].get(port)
            if value is None:
                continue
            if have_previous and value != previous:
                events.append((i, row['edge'], value))
            previous = value
            have_previous = True
        return events

    def check_pair(filtered_port, delayed_port):
        filtered = transitions(filtered_port)
        delayed = transitions(delayed_port)
        used = set()
        matched = 0

        for delayed_index, delayed_edge, delayed_value in delayed:
            candidates = [
                (j, event) for j, event in enumerate(filtered)
                if j not in used and event[0] < delayed_index and event[2] == delayed_value
            ]
            if not candidates:
                return (False, delayed_edge,
                        f'{delayed_port} changed to {delayed_value} without an earlier matching {filtered_port} transition')
            j, _ = candidates[0]
            used.add(j)
            matched += 1

        if len(used) != len(filtered):
            return (None, None,
                    f'{delayed_port} has not yet reflected every observed {filtered_port} transition; delay is unspecified')
        if matched == 0:
            return (None, None,
                    f'no {filtered_port}/{delayed_port} transition occurred in the trace')
        return (True, delayed[-1][1],
                f'{delayed_port} transitions follow earlier {filtered_port} transitions without imposing a delay count')

    scl = check_pair('fscl', 'dscl')
    if scl[0] is False:
        return scl
    sda = check_pair('fsda', 'dsda')
    if sda[0] is False:
        return sda
    if scl[0] is None or sda[0] is None:
        return (None, None, f'insufficient transition evidence: {scl[2]}; {sda[2]}')
    return (True, sda[1], f'{scl[2]}; {sda[2]}')

def decide(trace):
    def value(row, port):
        return row['outputs'].get(port, row['inputs'].get(port))

    history_scl = []
    history_sda = []
    saw_operation = False

    for row in trace:
        # Reset is not normal controller operation.  Reset also establishes
        # the starting source history for the delayed registers.
        if row['inputs'].get('nReset') == 0 or row['inputs'].get('rst') == 1:
            fscl = value(row, 'fscl')
            fsda = value(row, 'fsda')
            history_scl = [fscl] if fscl is not None else []
            history_sda = [fsda] if fsda is not None else []
            continue

        fscl = value(row, 'fscl')
        fsda = value(row, 'fsda')
        dscl = value(row, 'dscl')
        dsda = value(row, 'dsda')
        saw_operation = True

        if dscl is None or dsda is None or fscl is None or fsda is None:
            return (False, row.get('edge'),
                    'dSCL, dSDA, fscl, and fsda must be declared sampled signals')

        if history_scl and dscl not in history_scl:
            return (False, row.get('edge'),
                    'dSCL leads fscl: its value has not occurred in an earlier filtered state')
        if history_sda and dsda not in history_sda:
            return (False, row.get('edge'),
                    'dSDA leads fsda: its value has not occurred in an earlier filtered state')

        history_scl.append(fscl)
        history_sda.append(fsda)

    if not saw_operation:
        return (None, None, 'normal controller operation never occurred in this trace')
    return (True, None,
            'dSCL and dSDA contain values from earlier states of fscl and fsda, with no fixed delay imposed')

def decide(trace):
