        dsda = outputs.get('dsda')
        if fscl is None or fsda is None or dscl is None or dsda is None:
            return (False, row.get('edge'),
                    'normal operation must expose fscl, fsda, dscl, and dsda')

        seen_scl.add(fscl)
        seen_sda.add(fsda)

        if prev is not None:
            old_fscl, old_fsda = prev
