def decide(trace):
    active = []
    for i, row in enumerate(trace):
        if row['inputs'].get('ena') == 1:
            active.append((i, row))

    if not active:
        return (None, None, 'the enabled processing interval never occurred')

    event_seen = False
    otherwise_seen = False
    failures = []

    for pos, (i, row) in enumerate(active):
        out = row['outputs']
        fscl = out.get('fscl')
        fsda = out.get('fsda')
        dsda = out.get('dsda')
        busy = out.get('busy')

        event = fscl == 1 and fsda != dsda
        if event:
            event_seen = True
            expected = 1 if (dsda == 1 and fsda == 0) else 0
            if busy != expected:
                failures.append((row['edge'],
                    f'filtered SDA/delayed SDA event requires busy={expected}, got {busy}'))
            if i > 0:
                previous = trace[i - 1]
                previous_busy = previous['outputs'].get('busy')
                if previous_busy != expected and busy == expected:
                    pass
        else:
            otherwise_seen = True
            if pos > 0:
                previous_i, previous = active[pos - 1]
                if previous_i == i - 1 and previous['outputs'].get('fscl') == 1 and previous['outputs'].get('fsda') != previous['outputs'].get('dsda'):
                    pass
                elif busy != previous['outputs'].get('busy'):
                    failures.append((row['edge'],
                        'busy changed although filtered SDA equals delayed SDA or filtered SCL is low'))

    if failures:
        edge, detail = failures[0]
        return (False, edge, detail)
    if not event_seen or not otherwise_seen:
        return (None, None,
                'the trace exercised only one of the event and no-event observation cases')
    return (True, None,
            'busy reflects filtered SDA transitions against delayed SDA and remains unchanged otherwise')

def decide(trace):
    seen_event = False
    previous_active_busy = None
    previous_event = False

    for row in trace:
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})

        if inputs.get('ena') != 1:
            previous_active_busy = None
            previous_event = False
            continue

        busy = outputs.get('busy')
        fsda = outputs.get('fsda')
        dsda = outputs.get('dsda')
        fscl = outputs.get('fscl')

        if busy is None or fsda is None or dsda is None or fscl is None:
            return (None, row.get('edge'), 'required declared observable or filtered-value probe is absent')

        start = fscl == 1 and fsda == 0 and dsda == 1
        stop = fscl == 1 and fsda == 1 and dsda == 0
        event = start or stop
        new_event = event and not previous_event

        if new_event:
            seen_event = True
            expected = 1 if start else 0
            if busy != expected:
                name = 'START' if start else 'STOP'
                return (False, row.get('edge'),
                        f'filtered {name} transition was detected by fsda/dsda with fscl high, '
                        f'but busy was {busy}; expected {expected}')
        elif previous_active_busy is not None and busy != previous_active_busy:
            return (False, row.get('edge'),
                    'busy changed without a filtered SDA transition relative to dSDA while filtered SCL was high')

        previous_active_busy = busy
        previous_event = event

    if not seen_event:
        return (None, None, 'no enabled filtered START or STOP comparison event occurred in this trace')

    return (True, None, 'busy reflected each detected filtered START/STOP comparison event and remained unchanged otherwise')

