def decide(trace):
    from specflow.refmodel.temporal import after, edges, eventually, worst

    def holds(cond):
        def predicate(row):
            return all(
                row['outputs'].get(port, row['inputs'].get(port)) == value
                for port, value in cond.items()
            )
        return predicate

    def any_of(alternatives):
        predicates = [holds(condition) for condition in alternatives]
        return lambda row: any(predicate(row) for predicate in predicates)

    sda_rises = edges(trace, 'sda_i', 'rise')

    def applies(row):
        return (
            row['edge'] in sda_rises
            and row['inputs'].get('ena') == 1
            and row['inputs'].get('scl_i') == 1
        )

    windows = after(
        trace,
        applies,
        until=any_of([{'sto_condition': 1}]),
        aborts=any_of([{'nReset': 0}, {'rst': 1}])
    )

    return worst([
        eventually(
            window,
            lambda row: row['outputs'].get('sto_condition') == 1,
            strong=True,
            after_activation=True
        )
        for window in windows
    ])

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, worst

    rises = edges(trace, 'sda_i', 'rise')

    def opens(row):
        return (
            row['edge'] in rises and
            row['inputs'].get('scl_i') == 1 and
            row['inputs'].get('ena') == 1
        )

    def aborts(row):
        return (
            row['inputs'].get('nReset') == 0 or
            row['inputs'].get('rst') == 1
        )

    windows = after(
        trace,
        opens,
        until=lambda row: row['outputs'].get('sto_condition') == 1,
        aborts=aborts
    )

    return worst([
        eventually(
            window,
            lambda row: row['outputs'].get('sto_condition') == 1,
            strong=False,
            after_activation=True
        )
        for window in windows
    ])

