def decide(trace):
    from specflow.refmodel.temporal import TO_END, WHILE_ACTIVE, after, edges, eventually, never, worst

    def holds(conditions):
        def predicate(row):
            return all(
                row.get("outputs", {}).get(port, row.get("inputs", {}).get(port)) == value
                for port, value in conditions.items()
            )
        return predicate

    def any_conditions(alternatives):
        predicates = [holds(item) for item in alternatives]
        return lambda row: any(predicate(row) for predicate in predicates)

    aborts = any_conditions([
        {"nReset": 0},
        {"rst": 1},
    ])

    # A declared probe identifies the held clock-stretching situation.  The
    # route makes cmd_ack the observable consequence, so no acknowledgement
    # may occur during that situation.
    stretch_windows = after(
        trace,
        lambda row: holds({"ena": 1, "slave_wait": 1})(row),
        until=WHILE_ACTIVE,
        aborts=aborts,
    )
    stretch_verdicts = [
        never(window, lambda row: row["outputs"].get("cmd_ack") == 1)
        for window in stretch_windows
    ]

