    sync_rises = edges(trace, "scl_sync", "rise")
    sync_windows = after(
        trace,
        lambda row: (
            row["edge"] in sync_rises
            and row["inputs"].get("ena") == 1
            and row["outputs"].get("write_high_phase") == 1
        ),
        until=TO_END,
        aborts=aborts,
    )
    sync_verdicts = [
        eventually(
            window,
            lambda row: row["outputs"].get("cmd_ack") == 1,
            after_activation=True,
            strong=False,
        )
        for window in sync_windows
    ]

