from specflow.refmodel.temporal import TO_END, after, edges, eventually, never, worst


def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def active_write_high(row):
        return (
            row.get('inputs', {}).get('ena') == 1
            and out(row, 'write_high_phase') == 1
            and out(row, 'scl_oen') == 1
        )

    def aborted(row):
        return (
            row.get('inputs', {}).get('nReset') == 0
            or row.get('inputs', {}).get('rst') == 1
            or out(row, 'al') == 1
        )

    stretch_starts = after(
        trace,
        lambda r: active_write_high(r) and out(r, 'slave_wait') == 1,
        until=lambda r: (
            aborted(r)
            or not active_write_high(r)
            or out(r, 'slave_wait') != 1
        ),
        aborts=aborted,
    )

    stretch_checks = [
        never(w, lambda r: out(r, 'cmd_ack') == 1)
        for w in stretch_starts
    ]

    falling_edges = edges(trace, 'scl_sync', 'rise')
    sync_starts = after(
        trace,
        lambda r: r.get('edge') in falling_edges and active_write_high(r),
        until=lambda r: out(r, 'cmd_ack') == 1 or aborted(r),
        aborts=aborted,
    )

    sync_checks = [
        eventually(w, lambda r: out(r, 'cmd_ack') == 1, strong=True)
        for w in sync_starts
    ]

    if not stretch_checks and not sync_checks:
        return (None, None, 'no enabled WRITE clock-stretching or synchronization situation occurred')

    result = worst(stretch_checks + sync_checks)
    if result[0] is False:
        return result

    if stretch_checks and not sync_checks:
        # A quiet stretch check alone must not pass a design that never completes.
        release_edges = edges(trace, 'slave_wait', 'fall')
        completion = after(
            trace,
            lambda r: r.get('edge') in release_edges,
            until=TO_END,
            aborts=aborted,
        )
        completion_result = worst([
            eventually(w, lambda r: out(r, 'cmd_ack') == 1, strong=True)
            for w in completion
        ])
        if completion_result[0] is not True:
            return (None, completion_result[1], 'stretch handling was observed, but normal completion after release was not observed')
        return result

    if sync_checks and not stretch_checks:
        return (None, result[1], 'synchronization handling was observed without a stretching or normal-completion comparison case')

    return result

