from specflow.refmodel.temporal import TO_END, after, throughout, worst

def decide(trace):
    def wait_active(row):
        return (row['inputs'].get('ena') == 1 and
                row['outputs'].get('slave_wait') == 1)

    def wait_ended(row):
        return row['outputs'].get('slave_wait') == 0

    def reset_asserted(row):
        return (row['inputs'].get('nReset') == 0 or
                row['inputs'].get('rst') == 1)

    windows = after(trace, wait_active, until=wait_ended,
                    aborts=reset_asserted)
    if not windows:
        return (None, None, 'slave_wait never became active')

    paused = [
        throughout(
            w,
            lambda row: row['outputs'].get('cmd_ack') == 0,
            after_activation=True
        )
        for w in windows
    ]
    verdict = worst(paused)
    if verdict[0] is False:
        return verdict

    # The routed observation has two cases: no cmd_ack during the wait, and
    # completion after SCL is available again.  Without the second case the
    # trace does not distinguish this requirement from an inactive command.
    post_wait_ack = []
    for w in windows:
        if not w.closed or not w.rows:
            continue
        last_index = max(row['index'] for row in w.rows)
        for row in trace:
            if (row['index'] > last_index and
                    row['outputs'].get('slave_wait') == 0 and
                    row['outputs'].get('cmd_ack') == 1):
                post_wait_ack.append(row)
                break

    if not post_wait_ack:
        return (None, None,
                'slave_wait was observed with cmd_ack low, but no post-wait completion pulse was observed')

    return (True, post_wait_ack[0]['edge'],
            'cmd_ack remained low while slave_wait was active and completed after the wait ended')

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, throughout, worst

    def active_wait(row):
        return (
            row['outputs'].get('slave_wait') == 1
            and row['inputs'].get('ena') == 1
        )

    def reset(row):
        return (
            row['inputs'].get('nReset') == 0
            or row['inputs'].get('rst') == 1
        )

    windows = after(
        trace,
        active_wait,
        until=lambda r: r['outputs'].get('slave_wait') == 0,
        aborts=reset,
    )

    verdicts = []
    for w in windows:
        low = throughout(
            w,
            lambda r: r['outputs'].get('cmd_ack') == 0,
            after_activation=True,
        )
        if low[0] is False:
            verdicts.append((False, low[1], 'cmd_ack asserted while slave_wait was active; command completion occurred before the wait ended'))
            continue
        if low[0] is None:
            verdicts.append(low)
            continue

        if not w.closed or not w.rows:
            verdicts.append((None, None, 'slave_wait remained active to the end of the trace; no resumed command completion was observed'))
            continue

        end_index = max(r['index'] for r in w.rows)
        completion = [
            r for r in trace
            if r['index'] >= end_index
            and r['outputs'].get('cmd_ack') == 1
            and r['inputs'].get('nReset') != 0
            and r['inputs'].get('rst') != 1
        ]
        if not completion:
            verdicts.append((None, None, 'slave_wait ended, but the trace showed no later cmd_ack from which to distinguish resumed command progress'))
        else:
            verdicts.append((True, completion[0]['edge'], 'cmd_ack remained low during slave_wait and appeared only after the wait ended'))

    return worst(verdicts)

