def decide(trace):
    # `scl_oen` is the routed declared observable, but the obligation
    # specifies no output property that can be checked from it.
    _observable_present = any(
        "scl_oen" in row.get("outputs", {}) for row in trace
    )
    return (None, None, "The obligation defines the internal role of cnt but states no independently observable effect on scl_oen")

def decide(trace):
    previous = None
    observed = False

    for row in trace:
        outputs = row.get('outputs', {})
        inputs = row.get('inputs', {})
        scl_oen = outputs.get('scl_oen')
        if previous is None:
            previous = row
            continue

        prev_oen = previous.get('outputs', {}).get('scl_oen')
        active = outputs.get('fsm_active') == 1
        changed = scl_oen != prev_oen

        if active and changed:
            observed = True
            if inputs.get('ena') == 0:
                return (False, row.get('edge'),
                        'scl_oen changed while ena was low; bit-level timing was not enabled')
            if outputs.get('slave_wait') == 1:
                return (False, row.get('edge'),
                        'scl_oen changed while released SCL was stretched low')
            if outputs.get('cnt_zero') != 1:
                return (False, row.get('edge'),
                        'scl_oen changed without the declared cnt timing boundary')

        previous = row

    if not observed:
        return (None, None,
                'no active command phase transition was observed in this trace')
    return (True, None,
            'observed active-command scl_oen phase transitions only at cnt timing boundaries')

from specflow.refmodel.temporal import after

def decide(trace):
    def value(row, name):
        return row.get('outputs', {}).get(name,
               row.get('inputs', {}).get(name))

    def active(row):
        return value(row, 'fsm_active') == 1

    # fsm_active is the declared probe naming the state in which an
    # enabled supported command is executing.  The window closes when that
    # command is no longer active.
    windows = after(trace, active,
                   until=lambda r: value(r, 'fsm_active') == 0)

    verdicts = []
    for window in windows:
        seen_counter_boundary = False
        transitions = 0
        failure = None

        for row in window.rows:
            if value(row, 'cnt_zero') == 1:
                seen_counter_boundary = True

            pos = row['index']
            if pos == 0:
                continue
            previous = trace[pos - 1]
            changed = (value(previous, 'scl_oen') !=
                       value(row, 'scl_oen'))
            if not changed:
                continue

            transitions += 1
            if value(row, 'ena') == 0 or value(row, 'slave_wait') == 1:
                failure = (False, row['edge'],
                           'scl_oen changed while ena was low or slave_wait was asserted')
                break
            if not seen_counter_boundary:
                failure = (False, row['edge'],
                           'scl_oen changed before a cnt-derived timing boundary')
                break
            seen_counter_boundary = False

        if failure is not None:
            verdicts.append(failure)
        elif transitions == 0:
            verdicts.append((None, None,
                             'the active command window contained no observable scl_oen phase transition'))
        elif not window.closed:
            verdicts.append((None, None,
                             'the command remained active when the trace ended'))
        else:
            verdicts.append((True, window.rows[-1]['edge'],
                             'scl_oen phase transitions were paced by cnt-derived boundaries'))

    if not verdicts:
        return (None, None, 'fsm_active never rose; no command-execution window occurred')

    for verdict in verdicts:
        if verdict[0] is False:
            return verdict
    for verdict in verdicts:
        if verdict[0] is None:
            return verdict
    return (True, verdicts[-1][1],
            'all observed active-command scl_oen transitions followed cnt-derived timing boundaries')

def decide(trace):
    seen_situation = False
    seen_transition = False
    last_edge = None

    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        po = prev['outputs']
        oo = row['outputs']

        # The routed condition is an enabled command that is actually being
        # executed.  fsm_active is a declared probe, not a guessed encoding.
        active = bool(po.get('fsm_active', 0) or oo.get('fsm_active', 0))
        if not active:
            continue
        seen_situation = True

        if po.get('scl_oen') == oo.get('scl_oen'):
            continue
        seen_transition = True
        last_edge = row.get('edge')

        # A held low enable or an already-active stretch must not let the
        # command phase advance.  The transition into a stretch may itself
        # be the timed release of SCL, so only the preceding stretch state is
        # excluded here.
        if not bool(row['inputs'].get('ena', 1)):
            return (False, row.get('edge'),
                    'scl_oen changed while ena was low; timing progression was not paused')
        if bool(po.get('slave_wait', 0)):
            return (False, row.get('edge'),
                    'scl_oen changed while released SCL remained stretched low')

        if not bool(oo.get('cnt_zero', 0)):
            return (False, row.get('edge'),
                    'scl_oen changed without the declared cnt-zero bit-timing boundary')

    if not seen_situation:
        return (None, None, 'no enabled active supported-command phase occurred')
    if not seen_transition:
        return (None, None, 'no scl_oen phase transition was observed in the active command window')
    return (True, last_edge, 'all observed scl_oen phase transitions occurred at cnt-zero timing boundaries')

