def decide(trace):
    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def rising(name, i):
        if i == 0:
            return bool(out(trace[i], name))
        return bool(out(trace[i], name)) and not bool(out(trace[i - 1], name))

    results = []
    starts = [i for i in range(len(trace))
              if rising('fsm_active', i)
              and out(trace[i], 'ena') == 1
              and out(trace[i], 'rst') == 0
              and out(trace[i], 'nReset') == 1]

    for start in starts:
        base_clk_cnt = trace[start].get('inputs', {}).get('clk_cnt')
        divider_seen = False
        aborted = False
        completed = False
        divider_edge = None

        for j in range(start, len(trace)):
            row = trace[j]
            inputs = row.get('inputs', {})

            if inputs.get('clk_cnt') != base_clk_cnt:
                aborted = True
                break
            if (inputs.get('ena') != 1 or inputs.get('rst') == 1 or
                    inputs.get('nReset') == 0 or out(row, 'al') == 1 or
                    out(row, 'slave_wait') == 1 or out(row, 'scl_sync') == 1):
                aborted = True
                break

            if out(row, 'cnt_zero') == 1:
                divider_seen = True
                if divider_edge is None:
                    divider_edge = row.get('edge')

            if out(row, 'cmd_ack') == 1:
                completed = True
                if not divider_seen:
                    results.append((False, row.get('edge'),
                                    'cmd_ack occurred before a divider expiration; '
                                    'the counter was not observed decrementing from clk_cnt'))
                else:
                    results.append((True, row.get('edge'),
                                    'cmd_ack followed a divider expiration while clk_cnt was stable; '
                                    'no exact latency is required by the specification'))
                break

            if j > start and out(row, 'fsm_active') == 0:
                aborted = True
                break

        if not completed and not aborted:
            results.append((None, None,
                            'the timing-counter transaction did not complete in this trace'))

    if not results:
        return (None, None, 'the timing-counter operating situation never occurred')
    for result in results:
        if result[0] is False:
            return result
    for result in results:
        if result[0] is True:
            return result
    return (None, None, 'the timing-counter transaction was not completed without an abort')

def decide(trace):
