        return row.get('outputs', {}).get(name, default)

    def invalid(row, clk_value):
        inp = row.get('inputs', {})
        return (inp.get('rst', 0) == 1 or
                inp.get('nReset', 1) == 0 or
                inp.get('ena', 1) == 0 or
                out(row, 'al') == 1 or
                out(row, 'slave_wait') == 1 or
                out(row, 'scl_sync') == 1 or
                inp.get('clk_cnt') != clk_value)

    activations = []
    previous_active = 0
    for i, row in enumerate(trace):
        active = out(row, 'fsm_active') == 1
        if active and not previous_active:
            activations.append(i)
        previous_active = 1 if active else 0

    if not activations:
        return (None, None, 'no command-acceptance signature occurred: fsm_active never rose')

    saw_applicable = False
    for start in activations:
        clk_value = row_clk_cnt = trace[start].get('inputs', {}).get('clk_cnt')
        if invalid(trace[start], clk_value):
            continue
        saw_applicable = True
        divider_seen = False
        ended = False

        for i in range(start + 1, len(trace)):
            row = trace[i]
            if invalid(row, clk_value):
                ended = True
                break

            if out(row, 'cnt_zero') == 1:
                divider_seen = True

            if out(row, 'cmd_ack') == 1:
                if not divider_seen:
                    return (False, row.get('edge'),
                            'cmd_ack occurred before any divider expiration; expected completion after cnt was loaded from clk_cnt and decremented on successive clocks')
                return (True, row.get('edge'),
                        'cmd_ack followed a divider expiration with clk_cnt stable; no exact completion latency was imposed')

            if out(row, 'fsm_active') == 0:
                ended = True
                break

        if ended:
            continue

    if saw_applicable:
        return (None, None, 'command activity occurred, but this trace did not show an applicable divider-timed completion')
