def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, worst

    def value(row, name, default=None):
        return row.get('outputs', {}).get(name, default)

    def input_value(row, name, default=None):
        return row.get('inputs', {}).get(name, default)

    def active(row):
        return (value(row, 'fsm_active') == 1 and
                input_value(row, 'ena') == 1 and
                input_value(row, 'rst') == 0 and
                input_value(row, 'nReset') == 1)

    def completion(row):
        return value(row, 'cmd_ack') == 1

    def voided(row):
        return (input_value(row, 'rst') == 1 or
                input_value(row, 'nReset') == 0 or
                value(row, 'al') == 1 or
                value(row, 'slave_wait') == 1 or
                value(row, 'scl_sync') == 1)

    windows = after(trace, active, until=completion, aborts=voided)

    verdicts = []
    for window in windows:
        clk_cnt = input_value(window.rows[0], 'clk_cnt') if window.rows else None

        def divider_expired(row):
            return (value(row, 'cnt_zero') == 1 and
                    input_value(row, 'clk_cnt') == clk_cnt)

        verdicts.append(eventually(
            window,
            divider_expired,
            after_activation=False,
            strong=True))

    return worst(verdicts)

