def decide(trace):
    seq_ports = ('start_sequence', 'stop_sequence', 'read_sequence', 'write_sequence')

    def out(row, name):
        return row.get('outputs', {}).get(name)

    def active(row):
        return any(out(row, p) == 1 for p in seq_ports)

    def usable(row):
        return (out(row, 'ena') if 'ena' in row.get('outputs', {}) else row.get('inputs', {}).get('ena')) == 1 \
            and row.get('inputs', {}).get('rst') != 1 \
            and row.get('inputs', {}).get('nReset') != 0 \
            and out(row, 'slave_wait') != 1 \
            and out(row, 'scl_sync') != 1

    def seq_state(row):
        return tuple(out(row, p) for p in seq_ports)

    activations = []
    for i, row in enumerate(trace):
        if not (usable(row) and active(row) and out(row, 'cnt_zero') == 1):
            continue
        previous_cnt = out(trace[i - 1], 'cnt_zero') if i else 0
        if previous_cnt != 1:
            activations.append(i)

    if not activations:
        return (None, None, 'the timing-counter expiration did not occur during an enabled command sequence')

    for i in activations:
        baseline = out(trace[i], 'scl_oen')
        found_advance = False
        j = i + 1
        while j < len(trace):
            row = trace[j]
            if not usable(row) or not active(row):
                break
            if out(row, 'scl_oen') != baseline:
                found_advance = True
                break
            j += 1
        if not found_advance:
            return (False, trace[i]['edge'],
                    'counter expiration occurred, but scl_oen did not advance to the next command phase')

    saw_no_expiration_hold = False
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        if not (usable(prev) and usable(row) and active(prev) and active(row)):
            continue
        if seq_state(prev) != seq_state(row):
            continue
        if out(prev, 'cnt_zero') == 1 or out(row, 'cnt_zero') == 1:
            continue
        if out(prev, 'scl_oen') == out(row, 'scl_oen'):
            saw_no_expiration_hold = True
        else:
            return (False, row['edge'],
                    'scl_oen advanced during a command phase without a timing-counter expiration')

    if not saw_no_expiration_hold:
        return (None, None,
                'counter expiration and the resulting scl_oen advance were observed, but the no-expiration side of the routed observation was not exercised')

    return (True, None,
            'counter expiration enabled the observed scl_oen command-phase advance, and scl_oen remained unchanged without expiration')

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, stable, worst

    def out(row, name):
        return row.get('outputs', {}).get(name)

    def command_phase(row):
        inp = row.get('inputs', {})
        return (
            inp.get('ena') == 1 and
            inp.get('nReset') == 1 and
            inp.get('rst') != 1 and
            out(row, 'fsm_active') == 1 and
            any(out(row, phase) == 1 for phase in (
                'start_sequence', 'stop_sequence',
                'read_sequence', 'write_sequence')) and
            out(row, 'slave_wait') != 1 and
            out(row, 'scl_sync') != 1
        )

    def expired(row):
        return command_phase(row) and out(row, 'cnt_zero') == 1

    def not_expired_phase(row):
        return command_phase(row) and out(row, 'cnt_zero') != 1

    positive_windows = after(trace, expired, until=TO_END)
    nonexpired_windows = after(trace, not_expired_phase,
                               until=lambda row: command_phase(row) and
                               out(row, 'cnt_zero') == 1)

    if not positive_windows:
        return (None, None,
                'timing-counter expiration was not exercised in an enabled command phase')
    if not nonexpired_windows:
        return (None, None,
                'the routed non-expired command-phase case was not exercised')

    positive = [
        eventually(
            window,
            lambda row: out(row, 'scl_oen') != window.value('scl_oen'),
            strong=True,
            after_activation=False
        )
        for window in positive_windows
    ]
    negative = [stable(window, 'scl_oen') for window in nonexpired_windows]
    return worst(positive + negative)

def decide(trace):
    def o(row, name):
        return row.get('outputs', {}).get(name)

    sequence_ports = (
        'start_sequence',
        'stop_sequence',
        'read_sequence',
        'write_sequence',
    )

    def in_command_phase(row):
        return any(o(row, name) == 1 for name in sequence_ports)

    def usable(row):
        inputs = row.get('inputs', {})
        return (
            inputs.get('ena') == 1
            and inputs.get('rst') != 1
            and inputs.get('nReset') != 0
            and o(row, 'slave_wait') != 1
            and o(row, 'scl_sync') != 1
        )

    expirations = []
    for i, row in enumerate(trace):
        if not (usable(row) and in_command_phase(row) and o(row, 'cnt_zero') == 1):
            continue
        if i == 0 or o(trace[i - 1], 'cnt_zero') != 1:
            expirations.append(i)

    if not expirations:
        return (None, None,
                'the timing counter did not expire during an enabled command phase')

    saw_routed_effect = False
    saw_unobservable_expiration = False

    for start in expirations:
        baseline = o(trace[start], 'scl_oen')
        j = start + 1
        closed = False

        while j < len(trace):
            row = trace[j]
            if (
                row.get('inputs', {}).get('rst') == 1
                or row.get('inputs', {}).get('nReset') == 0
                or o(row, 'slave_wait') == 1
                or o(row, 'scl_sync') == 1
            ):
                break
            if not in_command_phase(row):
                closed = True
                break
            if o(row, 'scl_oen') != baseline:
                saw_routed_effect = True
                break
            j += 1

        if not saw_routed_effect:
            saw_unobservable_expiration = True

    if saw_routed_effect and not saw_unobservable_expiration:
        return (True, None,
                'counter expiration was followed by the routed command-phase scl_oen advance')

    if saw_routed_effect:
        return (None, None,
                'some expirations enabled a routed scl_oen advance, but another expiration had no observable scl_oen effect')

    return (None, trace[expirations[0]]['edge'],
            'counter expiration occurred, but clk_en is internal and no licensed scl_oen effect was observable')

