def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges

    def active(row):
        return (row['outputs'].get('fsm_active') == 1
                and row['inputs'].get('ena') == 1)

    def aborts(row):
        return (row['outputs'].get('al') == 1
                or row['inputs'].get('nReset') == 0
                or row['inputs'].get('rst') == 1)

    windows = after(
        trace,
        active,
        until=lambda r: r['outputs'].get('cmd_ack') == 1,
        aborts=aborts
    )

    if not windows:
        return (None, None, 'the active supported-command situation never occurred')

    changed_edges = edges(trace, 'scl_oen', 'change')
    saw_transition = False
    saw_unknown_window = False

    for window in windows:
        rows = window.rows[1:] if len(window.rows) > 1 else []
        transitions = [r for r in rows if r.get('edge') in changed_edges]

        if not transitions:
            saw_unknown_window = True
            continue

        saw_transition = True
        for row in transitions:
            if row['outputs'].get('cnt_zero') != 1:
                return (
                    False,
                    row.get('edge'),
                    'scl_oen changed at a command-phase boundary without the licensed counter-expiry/clk_en indication'
                )

    if saw_unknown_window or not saw_transition:
        return (
            None,
            None,
            'the active window did not provide an observable scl_oen phase transition to distinguish this rule'
        )

    return (
        True,
        None,
        'every observed scl_oen phase transition occurred with the licensed counter-expiry/clk_en indication'
    )

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, never, worst

    def active_supported(row):
        return (
            row['outputs'].get('fsm_active') == 1
            and row['inputs'].get('ena') == 1
            and row['inputs'].get('cmd') in (1, 2, 4, 8)
        )

    def any_condition(alternatives):
        def predicate(row):
            return any(
                all(
                    row['outputs'].get(port, row['inputs'].get(port)) == value
                    for port, value in condition.items()
                )
                for condition in alternatives
            )
        return predicate

    windows = after(
        trace,
