        until=any_condition([{'cmd_ack': 1}]),
        aborts=any_condition([
            {'al': 1},
            {'nReset': 0},
            {'rst': 1},
        ]),
    )

    changes = edges(trace, 'scl_oen', 'change')
    verdicts = []
    for window in windows:
        changed_rows = [row for row in window.rows if row['edge'] in changes]
        if not changed_rows:
            verdicts.append((None, None, 'no scl_oen phase transition was observed in the active command window'))
            continue

        verdicts.append(
            never(
                window,
