def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges

    def holds(row, name, value):
        return row.get('outputs', {}).get(name) == value

    def active_supported(row):
        return (holds(row, 'fsm_active', 1)
                and row.get('inputs', {}).get('ena') == 1
                and row.get('inputs', {}).get('cmd') in (1, 2, 4, 8))

    def aborts(row):
        return (row.get('inputs', {}).get('nReset') == 0
                or row.get('inputs', {}).get('rst') == 1
                or holds(row, 'al', 1))

    windows = after(
        trace,
        active_supported,
        until=lambda row: holds(row, 'cmd_ack', 1),
        aborts=aborts
    )

    if not windows:
        return (None, None, 'the active supported-command situation never occurred')

    scl_changes = edges(trace, 'scl_oen', 'change')
    saw_transition = False
    undecided = False

    for window in windows:
        rows = list(window.rows)
        if not rows:
            undecided = True
            continue

        activation_index = rows[0].get('index', -1)
        phase_changes = [
            row for row in rows[1:]
            if row.get('edge') in scl_changes
        ]

        if not phase_changes:
            undecided = True
            continue

        saw_transition = True
        previous_change_index = activation_index
        for change in phase_changes:
            change_index = change.get('index', -1)
            enabled = any(
                holds(row, 'cnt_zero', 1)
                for row in rows
                if previous_change_index <= row.get('index', -1) <= change_index
            )
            if not enabled:
                return (
                    False,
                    change.get('edge'),
                    'scl_oen advanced to another command phase without a preceding counter expiry asserting `clk_en`'
                )
            previous_change_index = change_index

    if undecided or not saw_transition:
        return (
            None,
            None,
            'no observable scl_oen phase transition was available to decide whether FSM advancement was gated by `clk_en`'
        )

    return (
        True,
        None,
        'each observed scl_oen phase transition had a preceding counter expiry asserting `clk_en`'
    )

