from specflow.refmodel.temporal import TO_END, after, eventually, worst


def _holds(cond):
    def predicate(row):
        return all(
            row['outputs'].get(port, row['inputs'].get(port)) == value
            for port, value in cond.items()
        )
    return predicate


def _any(alternatives):
    predicates = [_holds(condition) for condition in alternatives]
    return lambda row: any(predicate(row) for predicate in predicates)


def decide(trace):
    activation = _holds({'cmd': 4, 'ena': 1})
    closes = _any([{'cmd_ack': 1}])
    aborts = _any([
        {'al': 1},
        {'nReset': 0},
        {'rst': 1},
    ])

    windows = after(trace, activation, until=closes, aborts=aborts)
    verdicts = []

    for window in windows:
        # This is the route's stated stable-high WRITE condition.  fsda is
        # the declared filtered-SDA probe; raw sda_i is not substituted.
        qualifying = [
            row for row in window.rows
            if row['inputs'].get('din') == 1
            and row['outputs'].get('sda_oen') == 1
            and row['outputs'].get('sda_chk') == 1
            and row['outputs'].get('fsda') == 0
        ]
        if not qualifying:
            verdicts.append((None, None, 'no released-high WRITE arbitration-loss condition occurred'))
            continue

        verdicts.append(eventually(
            window,
            lambda row: (
                row['inputs'].get('din') == 1
                and row['outputs'].get('sda_oen') == 1
                and row['outputs'].get('sda_chk') == 1
                and row['outputs'].get('fsda') == 0
                and row['outputs'].get('al') == 1
            ),
            after_activation=True,
            strong=True,
        ))

    return worst(verdicts)

def decide(trace):
    from specflow.refmodel.temporal import after, eventually, throughout, worst

    def out(row, name, value=1):
        return row['outputs'].get(name) == value

    def inp(row, name, value=1):
        return row['inputs'].get(name) == value

    def phase(row):
        return (
            out(row, 'write_sequence') and
            out(row, 'write_high_phase') and
            out(row, 'sda_chk') and
            out(row, 'sda_oen', 1) and
            inp(row, 'ena', 1) and
            inp(row, 'din', 1)
        )

    def filtered_sda(row, value):
        return row['outputs'].get('fsda') == value

    def reset(row):
        return inp(row, 'nReset', 0) or inp(row, 'rst', 1)

    low_condition = lambda row: phase(row) and filtered_sda(row, 0)
    high_condition = lambda row: phase(row) and filtered_sda(row, 1)

    low_windows = after(
        trace,
        low_condition,
        until=lambda row: not low_condition(row),
        aborts=reset
    )
    high_windows = after(
        trace,
        high_condition,
        until=lambda row: not high_condition(row),
        aborts=reset
    )

    low_checks = [
        eventually(
            window,
            lambda row: out(row, 'al'),
            strong=True,
            after_activation=True
        )
        for window in low_windows
    ]
    high_checks = [
        throughout(
            window,
            lambda row: not out(row, 'al')
        )
        for window in high_windows
    ]

    return worst(low_checks + high_checks)

