def decide(trace):
    sequence_ports = [
        'start_sequence',
        'stop_sequence',
        'read_sequence',
        'write_sequence',
    ]
    saw_enabled_idle = False
    saw_command_sequence = False

    for row in trace:
        inputs = row['inputs']
        outputs = row['outputs']

        if inputs.get('nReset') == 0 or inputs.get('rst') == 1:
            continue
        if inputs.get('ena') != 1:
            continue

        active = outputs.get('fsm_active') == 1
        active_sequences = [
            port for port in sequence_ports
            if outputs.get(port) == 1
        ]

        if not active:
            saw_enabled_idle = True
            if active_sequences:
                return (
                    False,
                    row['edge'],
                    'FSM is idle but command sequence state(s) are active: '
                    + ', '.join(active_sequences)
                )
        else:
            saw_command_sequence = True
            if len(active_sequences) != 1:
                return (
                    False,
                    row['edge'],
                    'active FSM has %d command-sequence states active; expected exactly one'
                    % len(active_sequences)
                )

    if not saw_enabled_idle and not saw_command_sequence:
        return (None, None, 'enabled idle or command-sequence state never occurred')
    if not saw_command_sequence:
        return (
            None,
            None,
            'no recognized command-sequence state occurred; command encoding is not specified'
        )
    return (True, None, 'enabled FSM states match idle and single-command-sequence requirements')

def decide(trace):
    seqs = (
        'start_sequence',
        'stop_sequence',
        'read_sequence',
        'write_sequence',
    )
    saw_idle = False
    saw_active_sequence = False

    for row in trace:
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        edge = row.get('edge')

        # Reset aborts command processing; do not judge state relationships there.
        if inputs.get('nReset') == 0 or inputs.get('rst') == 1:
            continue

        active = outputs.get('fsm_active') == 1
        active_seqs = [p for p in seqs if outputs.get(p) == 1]

        if not active:
            saw_idle = True
            if active_seqs:
                return (
                    False,
                    edge,
                    'FSM is idle but command sequence state(s) are active: '
                    + ', '.join(active_seqs)
                )
        else:
            saw_active_sequence = True
            if len(active_seqs) != 1:
                return (
                    False,
                    edge,
                    'FSM is active but does not have exactly one active '
                    'command sequence; active sequence states: '
                    + (', '.join(active_seqs) if active_seqs else 'none')
                )

    if not saw_idle and not saw_active_sequence:
        return (None, None, 'no non-reset FSM state was observed')
    if saw_active_sequence:
        return (True, None, 'FSM activity corresponds to exactly one command-sequence state at a time')
    return (True, None, 'FSM remained idle with all command-sequence states inactive')

