def decide(trace):
    results = []
    active = []

    def out(row, port, default=None):
        return row.get('outputs', {}).get(port, default)

    def probe(row, name, default=False):
        return bool(row.get('outputs', {}).get(name, default))

    def reset_asserted(row):
        return row.get('inputs', {}).get('rst') == 1 or row.get('inputs', {}).get('nReset') == 0

    # The command encoding is intentionally not inspected: no authoritative
    # encoding table is present.  Recognize the generated START signature
    # instead: SDA changes to driven-low while SCL remains released-high.
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        is_start_completion = (
            probe(row, 'start_sequence') and
            out(prev, 'sda_oen') != 0 and
            out(row, 'sda_oen') == 0 and
            out(row, 'scl_oen') == 1
        )
        if is_start_completion:
            active.append(i)

    if not active:
        return (None, None, 'START completion activation never occurred')

    for start_i in active:
        scl_pulled_low = False
        ack_i = None
        aborted = False

        for j in range(start_i + 1, len(trace)):
            row = trace[j]
            if reset_asserted(row):
                aborted = True
                break

            if (not scl_pulled_low and
                    out(trace[j - 1], 'scl_oen') != 0 and
                    out(row, 'scl_oen') == 0):
                scl_pulled_low = True

            if out(row, 'cmd_ack') == 1:
                ack_i = j
                break

        if aborted:
            results.append((None, trace[start_i].get('edge'),
                            'START completion was aborted by reset'))
            continue

        if ack_i is None:
            results.append((False, trace[start_i].get('edge'),
                            'START completion occurred but cmd_ack was not asserted'))
            continue

        ack_row = trace[ack_i]
        if not scl_pulled_low:
            results.append((False, ack_row.get('edge'),
                            'SCL was not pulled low before command completion'))
            continue

        if ack_row.get('held') != 1:
            results.append((False, ack_row.get('edge'),
                            "cmd_ack was not high for exactly one clock cycle"))
            continue

        if ack_i + 1 >= len(trace):
            results.append((None, ack_row.get('edge'),
                            'cmd_ack was high for one observed clock, but its falling edge was not observed'))
            continue

        if out(trace[ack_i + 1], 'cmd_ack') == 1:
            results.append((False, ack_row.get('edge'),
                            "cmd_ack was not high for exactly one clock cycle"))
            continue

        results.append((True, ack_row.get('edge'),
                        'SCL was pulled low and cmd_ack was high for exactly one clock cycle'))

