from specflow.refmodel.temporal import TO_END, after, edges, eventually, throughout, worst


def decide(trace):
    def holds(cond):
        def predicate(row):
            return all(
                row['outputs'].get(port, row['inputs'].get(port)) == value
                for port, value in cond.items()
            )
        return predicate

    def any_alt(alternatives):
        predicates = [holds(condition) for condition in alternatives]
        return lambda row: any(predicate(row) for predicate in predicates)

    activation = lambda row: (
        holds({'cmd': 8, 'ena': 1})(row)
        and holds({'read_window': 1})(row)
    )
    aborts = any_alt([
        {'al': 1},
        {'nReset': 0},
        {'rst': 1},
    ])

    windows = after(
        trace,
        activation,
        until=holds({'scl_oen': 0}),
        aborts=aborts,
    )

    falling_edges = edges(trace, 'scl_oen', 'fall')
    verdicts = []
    for window in windows:
        verdicts.append(
            throughout(
                window,
                lambda row: row['outputs'].get('scl_oen') == 1,
                after_activation=True,
            )
        )
        verdicts.append(
            eventually(
                window,
                lambda row: row['edge'] in falling_edges,
                strong=True,
                after_activation=True,
            )
        )

    return worst(verdicts)

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def aborted(row):
        return (out(row, 'al') == 1 or
                row.get('inputs', {}).get('nReset') == 0 or
                row.get('inputs', {}).get('rst') == 1)

    verdicts = []
    activated = False
    previous_read_window = False
    i = 0

    while i < len(trace):
        row = trace[i]
        read_window = out(row, 'read_window') == 1
        ena = row.get('inputs', {}).get('ena') == 1
        opening = read_window and ena and not previous_read_window
        previous_read_window = read_window

        if not opening:
            i += 1
            continue

        activated = True
        interior = []
        j = i + 1
        aborted_attempt = False
        closed = False

        while j < len(trace):
            current = trace[j]

            if aborted(current):
                aborted_attempt = True
                break

            if out(current, 'scl_oen') == 0:
                closed = True
                break

            interior.append(current)
            j += 1

        if aborted_attempt:
            i = j + 1
            continue

        if not interior:
            verdicts.append((None, row.get('edge'),
                             'READ read window opened but contained no post-activation high-SCL state'))
        elif any(out(r, 'scl_oen') != 1 for r in interior):
            bad = next(r for r in interior if out(r, 'scl_oen') != 1)
            verdicts.append((False, bad.get('edge'),
                             'scl_oen was not high throughout the READ read window'))
        elif not closed:
            verdicts.append((False, trace[-1].get('edge'),
                             'scl_oen never became low after the READ read window'))
        else:
            verdicts.append((True, trace[j].get('edge'),
                             'scl_oen stayed high during the READ read window and then became low'))

        i = j + 1 if closed else len(trace)

    if not activated:
        return (None, None, 'READ read window never occurred in this trace')

    failures = [v for v in verdicts if v[0] is False]
    if failures:
        return failures[0]
    successes = [v for v in verdicts if v[0] is True]
    if successes and all(v[0] is not None for v in verdicts):
        return (True, successes[-1][1],
                'all observed READ read windows released SCL high and then pulled it low')
    if successes:
        return successes[-1]
    return (None, None, 'the READ read-window attempts were incomplete or aborted')

