            return (False, row['edge'], 'When an output enable is low, the corresponding line is driven low: sda_oen is low but sda_o is not low')
    if not active:
        return (None, None, 'the output-enable-low condition never occurred in this trace')
    return (True, None, 'When an output enable is low, the corresponding line is driven low for every exercised enable state')

