from specflow.refmodel.temporal import after, eventually, pulse, worst


def _holds(row, cond):
    for port, value in cond.items():
        values = row.get("outputs", {})
        actual = values.get(port)
        if actual is None:
            actual = row.get("inputs", {}).get(port)
        if actual != value:
            return False
    return True


def _any(conditions):
    return lambda row: any(_holds(row, condition) for condition in conditions)


def _label(verdict):
    ok, edge, detail = verdict
    return (ok, edge, "cmd_ack is asserted for exactly one `clk` cycle at the end of the sequence; " + detail)


def decide(trace):
    def sequence_active(row):
        return (
            _holds(row, {"start_sequence": 1}) or
            _holds(row, {"stop_sequence": 1}) or
            _holds(row, {"read_sequence": 1}) or
            _holds(row, {"write_sequence": 1})
        ) and row.get("inputs", {}).get("ena") == 1

    windows = after(
        trace,
        sequence_active,
        until=_any([{"cmd_ack": 1}]),
        aborts=_any([
            {"al": 1},
            {"nReset": 0},
            {"rst": 1}
        ])
    )

    verdicts = []
    for window in windows:
        verdicts.append(_label(eventually(
            window,
            lambda row: row.get("outputs", {}).get("cmd_ack") == 1,
            strong=True,
            after_activation=True
        )))
        verdicts.append(_label(pulse(
            window,
            "cmd_ack",
            width=1,
            active=1,
            after_activation=True
        )))

    return worst(verdicts)

from specflow.refmodel.temporal import TO_END, after, pulse, worst


def _holds(cond):
    def predicate(row):
        return all(
            row['outputs'].get(port, row['inputs'].get(port)) == value
            for port, value in cond.items()
        )
    return predicate


def _any(alternatives):
    predicates = [_holds(condition) for condition in alternatives]
    return lambda row: any(predicate(row) for predicate in predicates)


def decide(trace):
    # No authoritative encoding table is supplied for cmd.  The declared
    # sequence probes provide the port-level signatures of the four situations.
    sequence_probes = (
        'start_sequence',
        'stop_sequence',
        'read_sequence',
        'write_sequence',
    )
    aborts = _any([
        {'al': 1},
        {'nReset': 0},
        {'rst': 1},
    ])

    verdicts = []
    for probe in sequence_probes:
        applies = lambda row, probe=probe: (
            row['inputs'].get('ena') == 1
            and row['outputs'].get(probe) == 1
        )
        windows = after(
            trace,
            applies,
            until=_holds({'cmd_ack': 1}),
            aborts=aborts,
        )
        verdicts.extend(
            pulse(window, 'cmd_ack', width=1, active=1)
            for window in windows
        )

    return worst(verdicts)

from specflow.refmodel.temporal import after, edges, eventually, worst


def _holds(condition):
    def predicate(row):
        values = row.get("outputs", {})
        for port, expected in condition.items():
            actual = values.get(port)
            if actual is None:
                actual = row.get("inputs", {}).get(port)
            if actual != expected:
                return False
        return True
    return predicate


def _any(alternatives):
    predicates = [_holds(condition) for condition in alternatives]
    return lambda row: any(predicate(row) for predicate in predicates)


def decide(trace):
    aborts = _any([
        {"al": 1},
        {"nReset": 0},
        {"rst": 1},
    ])

    verdicts = []
    for probe in ("start_sequence", "stop_sequence",
                  "read_sequence", "write_sequence"):
        openings = edges(trace, probe, "rise")
        windows = after(
            trace,
            lambda row, openings=openings: row.get("edge") in openings,
            until=_holds({"cmd_ack": 1}),
            aborts=aborts,
        )

        for window in windows:
            response = eventually(
                window,
                _holds({"cmd_ack": 1}),
                strong=True,
                after_activation=True,
            )
            if response[0] is not True:
                verdicts.append(response)
                continue

            ack_rows = [
                row for row in window.rows
                if row.get("outputs", {}).get("cmd_ack") == 1
            ]
            if not ack_rows:
                verdicts.append((False, window.edge,
                                 "cmd_ack response was not observable at the sequence end"))
                continue

            ack = ack_rows[0]
            if ack.get("held") != 1:
                verdicts.append((
                    False,
                    ack.get("edge"),
                    f"cmd_ack was held for {ack.get('held')} clk cycle(s); expected exactly one clk cycle",
                ))
            else:
                verdicts.append((
                    True,
                    ack.get("edge"),
                    "cmd_ack was asserted for exactly one clk cycle at the sequence end",
                ))

    return worst(verdicts)

from specflow.refmodel.temporal import TO_END, after, edges, eventually, worst


def _out(row, port):
    return row.get("outputs", {}).get(port)


def _probe(row, port):
    return _out(row, port) == 1


def decide(trace):
    aborts = lambda row: (
        _out(row, "al") == 1
        or row.get("inputs", {}).get("nReset") == 0
        or row.get("inputs", {}).get("rst") == 1
    )

    terminal_events = [
        ("start_sequence", "scl_oen", "fall", "START"),
        ("stop_sequence", "sda_oen", "rise", "STOP"),
        ("read_sequence", "scl_oen", "fall", "READ"),
        ("write_sequence", "scl_oen", "fall", "WRITE"),
    ]

    verdicts = []
    for sequence, port, direction, name in terminal_events:
        event_edges = edges(trace, port, direction)
        windows = after(
            trace,
            lambda row, event_edges=event_edges, sequence=sequence:
                row.get("edge") in event_edges and _probe(row, sequence),
            until=TO_END,
            aborts=aborts,
            overlap=True,
        )

        for window in windows:
            response = eventually(
                window,
                lambda row: _out(row, "cmd_ack") == 1,
                strong=True,
                after_activation=True,
            )
            if response[0] is not True:
                verdicts.append(response)
                continue

            ack_index = None
            for i, row in enumerate(window.rows):
                if _out(row, "cmd_ack") == 1:
                    ack_index = i
                    break

            if ack_index is None:
                verdicts.append((None, window.edge,
                                 f"{name} terminal phase was observed, but the cmd_ack response is not fully observable"))
                continue

            ack_row = window.rows[ack_index]
            high_edges = 0
            ended = False
            for row in window.rows[ack_index:]:
                if _out(row, "cmd_ack") != 1:
                    ended = True
                    break
                high_edges += row.get("held", 1)

            if high_edges != 1:
                verdicts.append((False, ack_row.get("edge"),
                                 f"cmd_ack was high for {high_edges} clk cycle(s) after the {name} sequence; expected exactly one clk cycle"))
            elif not ended:
                verdicts.append((None, ack_row.get("edge"),
                                 f"cmd_ack was high for one observed clk cycle after the {name} sequence, but its falling edge is outside the trace"))
            else:
                verdicts.append((True, ack_row.get("edge"),
                                 f"cmd_ack was asserted for exactly one clk cycle at the end of the {name} sequence"))

    return worst(verdicts)

